INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヒヨリ", 100101, "", 1, "vo_empress_100101_001", 5, "", 1, "vo_empress_100101_001", "どんなに敵が大勢でも、みんなで\n力を合わせれば絶対大丈夫だよ！\nだから顔を上げてこう！\nごーごー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヒヨリ", 100103, "", 1, "vo_empress_100101_002", 5, "", 2, "vo_empress_100101_002", "ううっ、何度も戦う相手もいるけど\nあたし、負けたりなんてしないよ！\n今回だってみんなや騎士くんがいる\nフルパワーでいくよーっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヒヨリ", 100103, "", 1, "vo_empress_100101_003", 5, "", 3, "vo_empress_100101_003", "うぅ…すごい力…！\n…でも、なんだか悲しそう\nこの人の気持ちを知りたい\nだからこそ…勝たなきゃ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヒヨリ", 100102, "", 1, "vo_empress_100101_004", 5, "", 4, "vo_empress_100101_004", "騎士くんの力があれば、\nあたしは絶対負けないよ！\nみんなが笑顔でいられるように\n一緒にがんばろう！", 100101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユイ", 100203, "", 1, "vo_empress_100201_001", 5, "", 5, "vo_empress_100201_001", "わたしたちの世界のためにも\nこの世界のためにも、\n絶対に負けられない…！\nがんばろうね、騎士クン", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユイ", 100203, "", 1, "vo_empress_100201_002", 5, "", 6, "vo_empress_100201_002", "みんな、怪我したらすぐに教えて！\n…もう誰も失いたくないの\nそのために修行もしたんだから…\n大丈夫、絶対なんとかしてみせる！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ユイ", 100203, "", 1, "vo_empress_100201_003", 5, "", 7, "vo_empress_100201_003", "世界を『書き換え』するなんて…\nそんな未来、寂しいだけだよ…！\nお願い、これ以上みんなを\n傷つけないで…話を聞いて！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ユイ", 100202, "", 1, "vo_empress_100201_004", 5, "", 8, "vo_empress_100201_004", "感じるよ、騎士クンの気持ち…\n抱きしめられてるみたいに\nあったかい…\nぜんぶ終わらせよう！", 100201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "レイ", 100301, "", 1, "vo_empress_100301_001", 5, "", 9, "vo_empress_100301_001", "厳しい戦いになるだろうな\n安心してくれ、何があっても\nキミは守る。…いや、違うな\n一緒に、世界を守ろう", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "レイ", 100303, "", 1, "vo_empress_100301_002", 5, "", 10, "vo_empress_100301_002", "手ごわい相手ばかりだな…\nだが引き下がるわけにはいかない\nこちらにだって譲れないものが\nあるんだ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "レイ", 100303, "", 1, "vo_empress_100301_003", 5, "", 11, "vo_empress_100301_003", "くっ…なんて力だ…！\n防ぐだけで精一杯…だが、\n例え剣が折れたとしても、\n私は最後まで戦い続ける！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "レイ", 100302, "", 1, "vo_empress_100301_004", 5, "", 12, "vo_empress_100301_004", "感じるよ、キミからの愛\nこれがあれば、私はどんな\n敵にだって打ち勝てる！\n見せてやろう、一緒に！", 100301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミソギ", 100401, "", 1, "vo_empress_100401_001", 5, "", 13, "vo_empress_100401_001", "ミソギとにいちゃんはこれからも\n世界中を冒険して、ワクワクする\nお宝をたくさん見つけるんだ！\nワルモノなんかに邪魔させないよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミソギ", 100401, "", 1, "vo_empress_100401_002", 5, "", 14, "vo_empress_100401_002", "わわ、なんかヤバそうな雰囲気…\nこういう時こそミソギの出番だね！\nとっておきのイタズラ決めて、\nピンチもひっくり返しちゃうよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミソギ", 100403, "", 1, "vo_empress_100401_003", 5, "", 15, "vo_empress_100401_003", "うぅ…あの悪者、すごい迫力だよ…\nもしミソギたちが負けちゃったら、\nミソギもにいちゃんもこの世界も…\n全部おしまい、なんだよね…？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミソギ", 100402, "", 1, "vo_empress_100401_004", 5, "", 16, "vo_empress_100401_004", "ミソギたちが世界を救っちゃったら\nきっとみんなびっくりするよね！\nどんな顔して驚いてくれるかな…\nにひひ、なんかワクワクしてきた！", 100401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マツリ", 100501, "", 1, "vo_empress_100501_001", 5, "", 17, "vo_empress_100501_001", "歴代オールヒーロー大進撃ッス～！\n自分は新世代のエースってとこッス\nかね？　さあ、ついてくるッス……\nあれ？　みんなどこ？　待って～", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マツリ", 100501, "", 1, "vo_empress_100501_002", 5, "", 18, "vo_empress_100501_002", "敵は圧倒的な力で、こっちを絶望\nさせる気ッスかね？　だとしたら\n大誤算ッスよ！　むしろ自分の\n正義の魂に火をつけたんスから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "マツリ", 100503, "", 1, "vo_empress_100501_003", 5, "", 19, "vo_empress_100501_003", "足が……震えるッス……けど！\nこれは武者震いッス……！　だって\nヒーローは絶対に絶対にっ！\n敗北なんてしないんスから……っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "マツリ", 100502, "", 1, "vo_empress_100501_004", 5, "", 20, "vo_empress_100501_004", "さあ、手と手をつないで、\n二人で教えてやるッスよ！\nどんな物語でも、悪は必ずヒーロー\nに打ち倒されるってことを！", 100501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アカリ", 100603, "", 1, "vo_empress_100601_001", 5, "", 21, "vo_empress_100601_001", "ひゃぁんっ！\nもう、敵さんが脅かしてくるから\nアカリ、ヘンな声出ちゃいました…\nこういうの、よくないですよっ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アカリ", 100601, "", 1, "vo_empress_100601_002", 5, "", 22, "vo_empress_100601_002", "アカリ、お兄ちゃんとシタイコトが\nまだまだいっぱいあるんです！\nだから、私たちの大事な世界も…\n本気で守り抜いてみせますっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アカリ", 100603, "", 1, "vo_empress_100601_003", 5, "", 23, "vo_empress_100601_003", "うぅ…こんなに激しく攻められたら\nアカリ、もう壊れちゃいそうです…\nだけどまだまだ…戦えますっ！\nお兄ちゃんが一緒なんですからっ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アカリ", 100602, "", 1, "vo_empress_100601_004", 5, "", 24, "vo_empress_100601_004", "お兄ちゃんの愛を注いでもらって\nアカリ超絶パワーアップです！\nアカリらしく世界一かわいく、\n世界を救ってみせちゃいますよ！", 100601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミヤコ", 100701, "", 1, "vo_empress_100701_001", 5, "", 25, "vo_empress_100701_001", "アイツらが野放しだと、ミヤコは\n安心してプリンを食べられないの\n今日のプリンと明日のプリンの\nためにも、絶対負けないの！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミヤコ", 100702, "", 1, "vo_empress_100701_002", 5, "", 26, "vo_empress_100701_002", "前はミヤコ、悪いヤツに捕まって\n消されそうになって怖かったの…\nでも今度は全然怖くないの！\nオマエが一緒なら平気なの！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミヤコ", 100703, "", 1, "vo_empress_100701_003", 5, "", 27, "vo_empress_100701_003", "むうぅ～っ、アイツしつこいの！\nこうなったら、オマエにも\nミヤコのプリン分けてやるの！\nダブルプリンパワーで頑張るの！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミヤコ", 100702, "", 1, "vo_empress_100701_004", 5, "", 28, "vo_empress_100701_004", "アイツはどんなに強くたって、\n独りぼっちのさびしいヤツなの\nでもオマエにはミヤコがいるの！\nミヤコたちなら絶対に勝てるの！", 100701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユキ", 100801, "", 1, "vo_empress_100801_001", 5, "", 29, "vo_empress_100801_001", "相手が誰であれ、やることは同じ…\nそう…ボクの美しさを見せてあげる\nことさ！　予言しよう…絶世の美の\n前にはどんな敵もひれ伏すと、ね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユキ", 100801, "", 1, "vo_empress_100801_002", 5, "", 30, "vo_empress_100801_002", "少し待っていてくれる？　メイクを\n直さないと。避けられない戦いなら\nせめて美しいボクと戦えることを\n彼らには誇りに思ってほしいからね", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ユキ", 100801, "", 1, "vo_empress_100801_003", 5, "", 31, "vo_empress_100801_003", "どうせ倒れるなら美しいままで散り\nたいな。ふふ、難しい望みかな…？\nそれでもボクは、最後まで美しく\nあがいてみせるよ、キミと一緒にね", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ユキ", 100802, "", 1, "vo_empress_100801_004", 5, "", 32, "vo_empress_100801_004", "ボクがいて、キミがいる。ボクたち\nが勝つのに、これ以上の理由はない\nよね。だって美しい者が勝つ未来の\nほうが、美しいエンディングだもの", 100801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アンナ", 100901, "", 1, "vo_empress_100901_001", 5, "", 33, "vo_empress_100901_001", "災厄の嵐が吹き荒れ、世界の命運は\n風前の灯が如く儚い。だが絶望には\nまだ早い！　希望はここに在り！\n灯火を掲げよう、盟友シグルドよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アンナ", 100903, "", 1, "vo_empress_100901_002", 5, "", 34, "vo_empress_100901_002", "終焉の日、滅びの刻来たれり、か…\nだが、幾度も転生を繰り返しながら\n戦いつづけた我らの宿命を思えば、\nこの程度取るに足らない…はずだ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アンナ", 100903, "", 1, "vo_empress_100901_003", 5, "", 35, "vo_empress_100901_003", "くっ…なんという禍々しい魔力…！\nもはや世界の滅びも間近…しかし\n疾風の冥姫がここで退くわけには\nいかぬ！　しぶとく抗ってみせるぞ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アンナ", 100902, "", 1, "vo_empress_100901_004", 5, "", 36, "vo_empress_100901_004", "永遠の盟約で結ばれし魂の伴侶…\n世界を滅ぼさんとする災禍の剣も\nこの絆を断ち切ることはできない！\n覚悟するがいい、幻境竜后！！", 100901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マホ", 101001, "", 1, "vo_empress_101001_001", 5, "", 37, "vo_empress_101001_001", "【自警団】のギルドマスターとして\nしゃんとして恥ずかしない姿を\n見せなあきまへんなぁ…王子はん\nしゃなりしゃなり、いきまひょ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マホ", 101001, "", 1, "vo_empress_101001_002", 5, "", 38, "vo_empress_101001_002", "王子はん、服が破れてますえ？\nこれでよし…うん、完璧や♪\n戦いの中でも、王子はんには\n格好良う居てもらいたいさかいに♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "マホ", 101003, "", 1, "vo_empress_101001_003", 5, "", 39, "vo_empress_101001_003", "幻境竜后…大層なお名前してはる\nお后さまが勝負を挑んできはるなら\nうちも、マホマホ王国の姫として…\n正々堂々受けて立ちますえ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "マホ", 101002, "", 1, "vo_empress_101001_004", 5, "", 40, "vo_empress_101001_004", "強い愛で結ばれた王子と姫を\n引き裂くことは誰にもできまへん\n王子はん…ふたりで一緒に！\nハッピーエンドを迎えまひょ！", 101001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リノ", 101101, "", 1, "vo_empress_101101_001", 5, "", 41, "vo_empress_101101_001", "お兄ちゃんがいれば百人力士っ！\n妹パワーも全開でいきますよ～♪\nどんな敵でもドンドンこいですっ！\nあれ？　ちょっと違いました？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リノ", 101101, "", 1, "vo_empress_101101_002", 5, "", 42, "vo_empress_101101_002", "これぞまさに『四面そば』…\n敵多すぎでもう大盛りですけど\n秘密結社の一員として、妹として\nこの世界の平和は守り通しますっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "リノ", 101103, "", 1, "vo_empress_101101_003", 5, "", 43, "vo_empress_101101_003", "あれが幻境竜后…不思議な服…\nじゃなくて、空気がピリピリです…\nちょっとだけ怖いけど…妹として\n絶対に降参なんてしませんよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "リノ", 101102, "", 1, "vo_empress_101101_004", 5, "", 44, "vo_empress_101101_004", "私、もう迷いません！\nお兄ちゃんと一緒なら\nどんな敵だって倒しちゃいます！\n妹のポテンシャルは無限大ですよ！", 101101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ハツネ", 101201, "", 1, "vo_empress_101201_001", 5, "", 45, "vo_empress_101201_001", "どんなに大変な時でもキミと一緒に\nず～っと乗り越えてきたんだもん！\nだからっ、今回もきっと大丈夫！\n私の魔法できらーん☆　だよっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ハツネ", 101202, "", 1, "vo_empress_101201_002", 5, "", 46, "vo_empress_101201_002", "力を使いすぎると眠く…スヤァ…\nはっ、いけないいけない！\nキミ、私が寝ちゃったら起こして！\n…お、王子様のキスとかで…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ハツネ", 101203, "", 1, "vo_empress_101201_003", 5, "", 47, "vo_empress_101201_003", "も～！　容赦なさすぎだよぉ！\nそっ、それにさっきまでの戦いの\nせいで、ね、眠気がぁ～っ…\nハ、ハツネちゃん、ピ～ンチ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ハツネ", 101202, "", 1, "vo_empress_101201_004", 5, "", 48, "vo_empress_101201_004", "幻境竜后さんがどんなに強くても\n今のハツネちゃんは無敵なのだ～！\n大好きなキミと！　シオリンと！\nみんながいる世界を守っちゃうよ！", 101201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ナナカ", 101301, "", 1, "vo_empress_101301_001", 5, "", 49, "vo_empress_101301_001", "この世界にはね、たくさんの人の\n『好き』が詰まってるんだよ\nそれをぶち壊すなんて鬼畜の所業\nナナカちゃんが許しはしないぜ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ナナカ", 101301, "", 1, "vo_empress_101301_002", 5, "", 50, "vo_empress_101301_002", "見るからにヤバい奴らが勢ぞろい！\nでもみんなの世界が狙われてんのに\n日和ってる奴いる？いねえよなぁ！\n全員ぶっ飛ばして世界を救うぞ！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ナナカ", 101303, "", 1, "vo_empress_101301_003", 5, "", 51, "vo_empress_101301_003", "あとはラスボスを倒せば勝利ッ！\n第３部完！　…とはいかない感じ？\nていうか逆にピンチな気配？\nどっどうしよう、どうすれば！？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ナナカ", 101302, "", 1, "vo_empress_101301_004", 5, "", 52, "vo_empress_101301_004", "幻境竜后…確かに強敵だったね\nでも今はもう負ける気がしないかな\nだって私は、ただのナナカじゃない\n超ナナカちゃんだから…！", 101301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カスミ", 101401, "", 1, "vo_empress_101401_001", 5, "", 53, "vo_empress_101401_001", "あちらにもなかなかの陰謀家がいる\nようだね。彼女らの最大の誤算は\nここに希代の名探偵がいることさ！\nさあ助手くん。真実を勝ち取ろう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カスミ", 101401, "", 1, "vo_empress_101401_002", 5, "", 54, "vo_empress_101401_002", "仕方ない、こうなったら奥の手だ\nミスティ！　セオリー！　…って\nこらぁっ！　変身の最中は待って\nくれるのがお約束だよ！？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "カスミ", 101403, "", 1, "vo_empress_101401_003", 5, "", 55, "vo_empress_101401_003", "なっ…なんだい、この悪寒は…\n触れてはならない何か…いいや！\n名探偵たるもの巨悪に恐れをなす\nわけにはいかない。絶対に…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "カスミ", 101402, "", 1, "vo_empress_101401_004", 5, "", 56, "vo_empress_101401_004", "どんな哀しみでさえ、道理を穢す\n理由にしてはならない。さあ、\nお縄につくんだ。史上最大の迷宮\n事件…終わらせるのは…この私だ！", 101401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミサト", 101501, "", 1, "vo_empress_101501_001", 5, "", 57, "vo_empress_101501_001", "先生は…ううん、先生たちは。\n絶対に負けません。みんなに傷一つ\nつけさせたりはしないわ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミサト", 101501, "", 1, "vo_empress_101501_002", 5, "", 58, "vo_empress_101501_002", "とっても強大な敵ばかりね…\nでも、大丈夫。焦らず落ち着いて\n戦いましょう。先生がついてるわ\n長引いても、あきらめないで…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミサト", 101501, "", 1, "vo_empress_101501_003", 5, "", 59, "vo_empress_101501_003", "幻境竜后さんの力…すごいわ…\nううん、怖がってる暇なんてないの\n森のみんなを守るためにも…！\n好き勝手したら「めっ」ですからね", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミサト", 101502, "", 1, "vo_empress_101501_004", 5, "", 60, "vo_empress_101501_004", "あなたと一緒なら\n負けたりなんか絶対にしないわ\n最後の一撃まで、\nがんばりましょうね♪", 101501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "スズナ", 101601, "", 1, "vo_empress_101601_001", 5, "", 61, "vo_empress_101601_001", "ツヨそーな敵ばっかりで\nテン下げってカンジだけど\nとりま、うちとヒデサイが\n一緒なら乗り越えられるっしょ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "スズナ", 101601, "", 1, "vo_empress_101601_002", 5, "", 62, "vo_empress_101601_002", "あっ、まってヒデサイ\nマントずれてるから直してあげる\n…よし！　こーゆう時こそ\nおしゃれでテン上げしなきゃね♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "スズナ", 101601, "", 1, "vo_empress_101601_003", 5, "", 63, "vo_empress_101601_003", "おにヤバすぎて超わろ～…でもでも\nどうにかやるしかないっしょ～\n勝利のランウェイ遠すぎだけど\nうちら諦めんのはダメだよね～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "スズナ", 101602, "", 1, "vo_empress_101601_004", 5, "", 64, "vo_empress_101601_004", "アオハルでバイブス爆上げ♪\n今のうちらは、ムテキだよ～\nハッピーで、もにカワな未来だって\n一緒にゲットするしかないっしょ♪", 101601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カオリ", 101701, "", 1, "vo_empress_101701_001", 5, "", 65, "vo_empress_101701_001", "歌ったり踊ったり、\nキミと一緒にやりたいことが\nばんないあるからね～！\n絶対に負けられないさ～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カオリ", 101701, "", 1, "vo_empress_101701_002", 5, "", 66, "vo_empress_101701_002", "ううっ強そうな敵ばっかりさ～！\n長丁場の戦いにはやっぱりこれよ～\nサーターアンダギー！\n栄養付けて平和を守るさ～♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "カオリ", 101703, "", 1, "vo_empress_101701_003", 5, "", 67, "vo_empress_101701_003", "うぅ～、幻境竜后、でーじ強いね～\n私たちも引き下がる気はないよ～！\nどんなに時間がかかっても、絶対に\n諦めたりしないさ～！　だよね～？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "カオリ", 101702, "", 1, "vo_empress_101701_004", 5, "", 68, "vo_empress_101701_004", "キミのくれた情熱が、\n私の中で熱く燃え滾ってるよ！\n最高の一撃、キミに見せるさ～！", 101701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イオ", 101801, "", 1, "vo_empress_101801_001", 5, "", 69, "vo_empress_101801_001", "学校生活の邪魔はさせないわ\nだって私、みんなの先生だもの\n明日の授業も世界のことも\n全部守ってみせるんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イオ", 101801, "", 1, "vo_empress_101801_002", 5, "", 70, "vo_empress_101801_002", "やん！　なんて手ごわい人たちなの\nでも諦めないわ。難しい問題だって\n落ち着いてやればちゃんと解けるの\n戦いも同じよ…いきましょう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "イオ", 101803, "", 1, "vo_empress_101801_003", 5, "", 71, "vo_empress_101801_003", "これが、幻境竜后さんの力…圧倒\nされちゃいそう。でも、怖がってる\n場合じゃないわ。先生は絶対に、\nここから退かないわ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "イオ", 101802, "", 1, "vo_empress_101801_004", 5, "", 72, "vo_empress_101801_004", "二人の絆があれば、\n怖いものなんてないわ\n先生と力を合わせて─\nいきましょう♪", 101801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミミ", 102003, "", 1, "vo_empress_102001_001", 5, "", 73, "vo_empress_102001_001", "す、すごく強そうな人がいっぱい…\nミミ、怖くてぶるぶるしちゃうけど\nでも泣いちゃったりはしないよっ\nおにいちゃんがいっしょだもん…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミミ", 102003, "", 1, "vo_empress_102001_002", 5, "", 74, "vo_empress_102001_002", "プチグリフォンさんもハナちゃんも\nみゅ～ちゃんも…きっとみんな、\nミミのこと応援してくれてるよね\nだからミミも、がんばるよっ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミミ", 102003, "", 1, "vo_empress_102001_003", 5, "", 75, "vo_empress_102001_003", "あ、あの竜の人…本気になったら、\nすごく強そうだよ…！このままじゃ\nみんなもミミたちも負けちゃう…？\nやだ、ミミそんなのいやだよっ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミミ", 102002, "", 1, "vo_empress_102001_004", 5, "", 76, "vo_empress_102001_004", "おにいちゃんがくれた元気、\n今度はミミたちから届けようね\nもう大丈夫、心配しないでって…\n世界中の、大切なお友だちに…！", 102001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クルミ", 102101, "", 1, "vo_empress_102101_001", 5, "", 77, "vo_empress_102101_001", "怖い人たちがいっぱいですぅ…！\n…でも、みんな頑張ってる…私も\nベルルちゃんみたいに勇気を出して\n…祝福の音を鳴らしましょう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クルミ", 102101, "", 1, "vo_empress_102101_002", 5, "", 78, "vo_empress_102101_002", "お兄ちゃん、私、がんばりますぅ\n『ロスト』したお父さんたちの\nためにも…！　怖い時こそ前を見て\n戦ってみせますからっ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クルミ", 102101, "", 1, "vo_empress_102101_003", 5, "", 79, "vo_empress_102101_003", "っ…すごい迫力ですぅ…！\nでも…絶望は必ず乗り越えられる\n胸の中の、希望の音色を信じて…\n逃げたりなんか、しませんよぅ…っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クルミ", 102102, "", 1, "vo_empress_102101_004", 5, "", 80, "vo_empress_102101_004", "みんなに勇気を与えるために\n主役にも英雄にもなってみせますぅ\nお兄ちゃんがいてくれるなら\n私はなんでもできるんです…！", 102101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヨリ", 102201, "", 1, "vo_empress_102201_001", 5, "", 81, "vo_empress_102201_001", "こ、これくらいの敵、問題ないわ！\nほんとはちょっと怖いけど…\nゲームの世界を救うことくらい\nこっちは慣れっこなんだから…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヨリ", 102201, "", 1, "vo_empress_102201_002", 5, "", 82, "vo_empress_102201_002", "ここで私たちが負けたら、\n世界が終わっちゃうなんて…\n絶対に認めるわけにはいかないわ！\nアンタも覚悟決めなさいよっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヨリ", 102203, "", 1, "vo_empress_102201_003", 5, "", 83, "vo_empress_102201_003", "ここからが本当の戦いってこと？\nならもう、とことんやってやるわ！\nゲーマーってのは、敵が手強いほど\n燃えてくる生き物なのよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヨリ", 102202, "", 1, "vo_empress_102201_004", 5, "", 84, "vo_empress_102201_004", "絶対に帰りたい理由ができた…\nそう思うだけで、いくらでも力が\n湧いてくるの。これならもう、\n文句なしの勝ち確よねっ！", 102201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アヤネ", 102301, "", 1, "vo_empress_102301_001", 5, "", 85, "vo_empress_102301_001", "私もみんなと一緒に戦うよ！\n悪い人たちはフルスイングで\nあっという間に倒しちゃうから！\n『おうっ！　全員かかってこい！』", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アヤネ", 102303, "", 1, "vo_empress_102301_002", 5, "", 86, "vo_empress_102301_002", "本当はちょっとだけ怖いけど…\nぷうきちもお兄ちゃんも一緒だもん\n力を合わせて世界を守っちゃうよ\n絶対に負けないんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アヤネ", 102303, "", 1, "vo_empress_102301_003", 5, "", 87, "vo_empress_102301_003", "ううっあの人、すごく怖いけど\n逃げないよ、戦うって決めたもん\nね、お兄ちゃん、ぷうきち！\n『ここが踏ん張りどころだぞ！』", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アヤネ", 102302, "", 1, "vo_empress_102301_004", 5, "", 88, "vo_empress_102301_004", "お兄ちゃんが約束してくれたもん\n今の私ならどんな悪いやつにも\n負けないよ！　宇宙人でもなんでも\n一撃で追い返しちゃうんだから♪", 102301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "スズメ", 102503, "", 1, "vo_empress_102501_001", 5, "", 89, "vo_empress_102501_001", "大変なことになっちゃいましたね…\nで、でも怖がっていられません！\nお嬢さまのことも、あなたのことも\n私が精一杯お支えします！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "スズメ", 102503, "", 1, "vo_empress_102501_002", 5, "", 90, "vo_empress_102501_002", "世界の命運がかかってますから\nドジなんてしてられません！\n…って、ああっ！　言ったそばから\nまた魔法が暴走しちゃいましたっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "スズメ", 102503, "", 1, "vo_empress_102501_003", 5, "", 91, "vo_empress_102501_003", "す、すごい力です…！\nでもお嬢さまや大切な人をおいて\n逃げるわけにはいきません！\nどこまでもお供します…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "スズメ", 102502, "", 1, "vo_empress_102501_004", 5, "", 92, "vo_empress_102501_004", "大切な人と力を合わせれば、\nドジな私でも世界を救えるんです！\n世界規模…いえ、宇宙規模の大掃除\n始めちゃいますよ～っ！", 102501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リン", 102603, "", 1, "vo_empress_102601_001", 5, "", 93, "vo_empress_102601_001", "ええー？　こんだけ人数いるならさ\n一人ぐらいいなくても…\n…って空気じゃないわけね\nはいはい、あたしも働きますよー", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リン", 102603, "", 1, "vo_empress_102601_002", 5, "", 94, "vo_empress_102601_002", "うぅ…あんなのもうバグでしょ！？\nこんな無理ゲーに参戦したんだもん\n終わったらしばらく働かないから！\nダラダラゴロゴロするからね～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "リン", 102603, "", 1, "vo_empress_102601_003", 5, "", 95, "vo_empress_102601_003", "見てよあのビジュアルさー\nまさにラスボスって感じじゃん…\nでも、どんなゲームでもボスは\n倒せるわけだし…はぁ、やるかー", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "リン", 102602, "", 1, "vo_empress_102601_004", 5, "", 96, "vo_empress_102601_004", "ここまで来たら後には退けないし\n正真正銘のラスボス戦ってんなら\nあたしも─気合い入れて\n少しぐらいイイとこ見せないとね！", 102601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "エリコ", 102701, "", 1, "vo_empress_102701_001", 5, "", 97, "vo_empress_102701_001", "有象無象のクズ虫が、私たちの\n幸せを阻もうとしているようですね\nあぁ、なんて忌々しいのでしょう…\n残らずすり潰しますわ、クスクス…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "エリコ", 102701, "", 1, "vo_empress_102701_002", 5, "", 98, "vo_empress_102701_002", "クスクス…あら、失礼しましたわ\nこの連中を駆逐すれば、私たちの\n絆はより強く…そんな想像をしたら\n思わず…クスクスクス、クスクス", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "エリコ", 102703, "", 1, "vo_empress_102701_003", 5, "", 99, "vo_empress_102701_003", "あの女…下らない言葉であなた様を\n誑かそうとしたとか。万死に値する\n罪…身の程を思い知らせてやるまで\n決して退きはしませんわ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "エリコ", 102702, "", 1, "vo_empress_102701_004", 5, "", 100, "vo_empress_102701_004", "『壊し屋』と呼ばれる私ですが…\n今はこの力、創るために振るいます\nあなた様との愛、未来…\nクスクス…さあ参りましょう…♪", 102701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "サレン", 102801, "", 1, "vo_empress_102801_001", 5, "", 101, "vo_empress_102801_001", "しっかり頭数揃えてきたわね…\nでもこの程度の力に屈するような\nあたしたちじゃないんだから\nあんたも、サポート頼んだわよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "サレン", 102801, 1, 1, "vo_empress_102801_002", 3, 10000, 102, "vo_empress_102801_002", "ちょっと！　なんか向こうに\n教育に悪そうなのがいるんだけど！\nあいつは子どもたちの目に入る前に\nあたしたちで倒すわよ。いい？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "サレン", 102803, "", 1, "vo_empress_102801_003", 5, "", 103, "vo_empress_102801_003", "もう、強すぎて参っちゃうわね…\nでも諦めるわけにはいかないわ\nこっちだって守らなきゃいけない\nものがたくさんあるんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "サレン", 102802, "", 1, "vo_empress_102801_004", 5, "", 104, "vo_empress_102801_004", "いつも以上に負ける気がしないわ\nこれもあんたと気持ちが通じた\nおかげね。あんたが側にいる限り、\nあたしはずっと無敵なんだから！", 102801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ノゾミ", 102903, "", 1, "vo_empress_102901_001", 5, "", 105, "vo_empress_102901_001", "この世界が終わっちゃうって…\nアイドル活動も卒業ってコト！？\nファンのみんなが黙ってないよ！\nもちろん私だって…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ノゾミ", 102903, "", 1, "vo_empress_102901_002", 5, "", 106, "vo_empress_102901_002", "どんな強い敵にだって屈しない…\n歌って踊って戦うアイドルになる！\nあの日に誓った願い、私の希望！\n今こそ、果たして見せるんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ノゾミ", 102903, "", 1, "vo_empress_102901_003", 5, "", 107, "vo_empress_102901_003", "幻境竜后…ダンスも歌も、あなたに\nとって価値はないかもしれないけど\n私はこのステージから逃げたり\nなんてしない！　アイドルとして！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ノゾミ", 102901, "", 1, "vo_empress_102901_004", 5, "", 108, "vo_empress_102901_004", "星を書き換えるなんてすごい発想…\nプロデューサーとか向いてるかも？\nって、今はそんな場合じゃないか！\n覚悟してよね、幻境竜后！", 102901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ニノン", 103001, "", 1, "vo_empress_103001_001", 5, "", 109, "vo_empress_103001_001", "ショーグンの天下統一を阻む者は\n誰であろうと許しまセン！\nショーグン！　ここはチューシン\nニノンにお任せアーレー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ニノン", 103001, "", 1, "vo_empress_103001_002", 5, "", 110, "vo_empress_103001_002", "むむむ…待ち受けているのは強敵\nばかり…それでも退きまセン！\n超烈火之紅蓮旋風で、\nまとめて討ち取ってみせまショウ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ニノン", 103003, "", 1, "vo_empress_103001_003", 5, "", 111, "vo_empress_103001_003", "な、なんて強さ…このままでは、\nワタシたちは負けてしまいます…\n…いいえ。いいえ！　ショーグンの\nためにも、諦めることなど…っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ニノン", 103002, "", 1, "vo_empress_103001_004", 5, "", 112, "vo_empress_103001_004", "感じマス、ショーグンの愛を…！\n今ならどんな敵が来ても、\nカッサイ、ボンサイ、\nオチャノコサイサイデース！", 103001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シノブ", 103101, "", 1, "vo_empress_103101_001", 5, "", 113, "vo_empress_103101_001", "この世界が、明日を迎えることなく\n滅んでしまうかもしれない…\n運命の岐路が、目の前にあります\n抗えるのは、私たちだけです…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シノブ", 103101, "", 1, "vo_empress_103101_002", 5, "", 114, "vo_empress_103101_002", "何よりも色濃い死の気配が、\n世界に満ちていくのを感じます\nでも、倒れるわけにはいきません\n最後まで戦いましょう、全力で", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "シノブ", 103103, "", 1, "vo_empress_103101_003", 5, "", 115, "vo_empress_103101_003", "これほどまでに強大な力なんて…\n占いも、未来は滅びの闇に覆われ\nつつある、と出ています…それでも\n希望を手放すわけには…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "シノブ", 103101, "", 1, "vo_empress_103101_004", 5, "", 116, "vo_empress_103101_004", "命ある者にとって、死の運命は\n決して避けられないもの…\nでも、今この時ではないはずです\n戦いましょう、未来のために…！", 103101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アキノ", 103201, "", 1, "vo_empress_103201_001", 5, "", 117, "vo_empress_103201_001", "これ以上の狼藉は許しません！\nウィスタリア家の名に懸けて、\nこの世界の人々を守ります…必ずや\n貴人としての役目を果たしますわ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アキノ", 103201, "", 1, "vo_empress_103201_002", 5, "", 118, "vo_empress_103201_002", "互いを利するウィンウィンの関係\nそれが商売の鉄則です。力を振るい\n一方的に望みを押し付けるなんて、\n倒産まっしぐらですわよっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アキノ", 103203, "", 1, "vo_empress_103201_003", 5, "", 119, "vo_empress_103201_003", "幻境竜后…すさまじい力ですわね\n世界を意のままにするという野望も\n決して絵空事ではないのでしょう…\nそれでも私は…諦めませんわよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アキノ", 103202, "", 1, "vo_empress_103201_004", 5, "", 120, "vo_empress_103201_004", "人々を守ることが力ある者の務め…\nそしてあなたさまと共に生きること\nそれが私の務めであり願いですわ！\nこの想いは、止まりませんわよ！", 103201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マヒル", 103301, "", 1, "vo_empress_103301_001", 5, "", 121, "vo_empress_103301_001", "こんな舞台で漫才したって\nみんなもお天道さんもどんよりだべ\n安心して笑ってられる世界を\nオラたちで取り戻すど！　おー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マヒル", 103301, "", 1, "vo_empress_103301_002", 5, "", 122, "vo_empress_103301_002", "お、おっかねぇ連中だ…！\nでも…スベっちまう怖さに比べりゃ\nマシだべな！　あははっ！\nみんなの笑顔は、オラが守るべ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "マヒル", 103303, "", 1, "vo_empress_103301_003", 5, "", 123, "vo_empress_103301_003", "あの子、芸人として光りそうだべな\n幻境竜后なんて仰々しい名前も…\nノーヴィジョンズノープロブレム！\n…あたた！　激しいツッコミだべ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "マヒル", 103302, "", 1, "vo_empress_103301_004", 5, "", 124, "vo_empress_103301_004", "逆境も笑顔で切り開く…\nあんちゃんと一緒なら\nできる気がすんだ\nオラたちの芸人魂、見せてやるべ！", 103301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユカリ", 103401, "", 1, "vo_empress_103401_001", 5, "", 125, "vo_empress_103401_001", "元…ううん、正しき聖騎士として\nここでやらなきゃいつやるのよ…！\n必ずみんなを守りきってみせるわ\n怪我をした人は私のところへ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユカリ", 103401, "", 1, "vo_empress_103401_002", 5, "", 126, "vo_empress_103401_002", "…んぐっ…ごくっ…ぷは～っ♪\nよぉし気合十分らわ～っ！\nこら～幻境竜后～っ！　隠れて\nないでかかってきなさ～い！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ユカリ", 103403, "", 1, "vo_empress_103401_003", 5, "", 127, "vo_empress_103401_003", "ひっく…ふぇ？　な、なに……？\nと、とっても大きいのが見えりゅ…\n…なっ、なによこれえぇぇ！\nこ、これが幻境竜后の姿なのぉ～っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ユカリ", 103402, "", 1, "vo_empress_103401_004", 5, "", 128, "vo_empress_103401_004", "私は無敵らのよ～♪　この世界と\nキミと築く\n素敵な未来のために…幻境竜后！\nぶっとばしてやるわぁ～っ！", 103401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "キョウカ", 103603, "", 1, "vo_empress_103601_001", 5, "", 129, "vo_empress_103601_001", "ここで私たちが諦めたら、このまま\n世界が終わっちゃう！　そんなの\n絶対ダメです！　負けられません！\n私たちで全部退治しちゃいますよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "キョウカ", 103603, "", 1, "vo_empress_103601_002", 5, "", 130, "vo_empress_103601_002", "うぅ、ふしんしゃがいっぱいです！\n…でも、このくらいへっちゃらです\nお母さんが心配する前に、早く\n片付けておうちに帰りましょう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "キョウカ", 103601, "", 1, "vo_empress_103601_003", 5, "", 131, "vo_empress_103601_003", "あれが私たちの敵、幻境竜后…\nほ、本当に勝てるんでしょうか…？\n立ってるだけで体が震えて…でも、\n弱気になっちゃダメですよねっ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "キョウカ", 103602, "", 1, "vo_empress_103601_004", 5, "", 132, "vo_empress_103601_004", "正直に言うと…まだ少し怖いです\n我慢したって怖くて体が震えます\nでも、あなたがいてくれるから…\n勇気だって同じくらい湧いてきます", 103601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "トモ", 103701, "", 1, "vo_empress_103701_001", 5, "", 133, "vo_empress_103701_001", "滅ぼすための力に、守るための力が\n屈するわけにはいかないよ。\nこの剣の誇りに賭けて、必ず止める\nさあ、来い！　ミクマ流が相手だ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "トモ", 103701, "", 1, "vo_empress_103701_002", 5, "", 134, "vo_empress_103701_002", "追いかけっこでもしようか\n鬼さんこちら♪　…って、まだ\n来るの！？　不意打ちされる側に\nなるのは趣味じゃないんだけどな！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "トモ", 103701, "", 1, "vo_empress_103701_003", 5, "", 135, "vo_empress_103701_003", "踏み込めない…踏み込む隙がない…\n向きあってるだけで精一杯なんて…\nで、でも…こんなところで\n剣を捨てるわけにはっ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "トモ", 103702, "", 1, "vo_empress_103701_004", 5, "", 136, "vo_empress_103701_004", "勝機は私の中にあったんだ…！\nあなたとの、\n一番強くて絶対に消えない絆\nそれが、あいつを倒す力をくれる！", 103701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シオリ", 103801, "", 1, "vo_empress_103801_001", 5, "", 137, "vo_empress_103801_001", "手ごわい相手ですね…\nでも、不思議と怖くありません\nあなたと力を合わせれば\n何とかなるって信じていますから", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シオリ", 103801, "", 1, "vo_empress_103801_002", 5, "", 138, "vo_empress_103801_002", "あなたの応援で、私の胸に\n愛と希望が満ち溢れています…\n今こそ魔法狩人ピュアリー★シオリ\nに大変身する時なのかも…？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "シオリ", 103803, "", 1, "vo_empress_103801_003", 5, "", 139, "vo_empress_103801_003", "とてつもない力ですね…\nでも、諦めたくありません\n何度だって立ち上がってみせます\n今までと同じように…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "シオリ", 103802, "", 1, "vo_empress_103801_004", 5, "", 140, "vo_empress_103801_004", "今の私に怖いものなんてありません\nあなたとの愛の力がありますから♪\n…少し舞い上がり過ぎですかね？\nふふ、気を引き締めてがんばります", 103801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アオイ", 104001, "", 1, "vo_empress_104001_001", 5, "", 141, "vo_empress_104001_001", "進んで目立ちたくはないですけど…\nと、ともっ…友達を守るためなら！\nＢＢ団として、勇気を振り絞って…\n団長さんと一緒に戦います！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アオイ", 104002, "", 1, "vo_empress_104001_002", 5, "", 142, "vo_empress_104001_002", "いいい、一緒に戦う仲間がこんなに\nいてくれるなんて、こ、心強いの\n助太郎～っ！　私も末席で参加し…\nじゃなくてっ！　全力で戦います！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アオイ", 104003, "", 1, "vo_empress_104001_003", 5, "", 143, "vo_empress_104001_003", "ううっ、手も足も声も震えてます…\nで、でも逃げも隠れもしませんよっ\n逃げたらぼっちが廃ります！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アオイ", 104002, "", 1, "vo_empress_104001_004", 5, "", 144, "vo_empress_104001_004", "私はひとりぼっちじゃない…\n団長さんと繋がった絆があるから\nどんな敵だって怖くないですっ！\n行きましょう、団長さんっ！", 104001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "チカ", 104203, "", 1, "vo_empress_104201_001", 5, "", 145, "vo_empress_104201_001", "やめてくれる気はなさそうです\nそれなら私も、絶対にここを\n動きはしません…！　だって\n私は……ワガママですからっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "チカ", 104201, "", 1, "vo_empress_104201_002", 5, "", 146, "vo_empress_104201_002", "私の唱喚術は人を守るためのもの…\nこの世界の森羅万象を護るための\nもの。今こそ、声の限り歌います\nこの子たちと、あなたと共に！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "チカ", 104203, "", 1, "vo_empress_104201_003", 5, "", 147, "vo_empress_104201_003", "精霊たちが震えてる…今までの\n敵とは訳が違うってことですよね…\n私もここに立っているのが精一杯…\n怖いけど…でも！　退きません…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "チカ", 104201, "", 1, "vo_empress_104201_004", 5, "", 148, "vo_empress_104201_004", "今なら歌える気がします。ずっと\n探していた、誰かの心を震わせる歌\n幻境竜后…孤独なあなたの心にも\n私たちの歌が届くように…！", 104201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マコト", 104301, "", 1, "vo_empress_104301_001", 5, "", 149, "vo_empress_104301_001", "敵さんがどんだけ強くったって\n後には退けねぇんだ！　そうだろ、\nさぁ、覚悟しやがれよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "マコト", 104301, "", 1, "vo_empress_104301_002", 5, "", 150, "vo_empress_104301_002", "くっ、敵の連中、ずいぶんな戦力\n揃えてきやがった。けど、\n数でも気合でも負けやしねぇ！\nあたしが嚙み砕いてやる！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "マコト", 104303, "", 1, "vo_empress_104301_003", 5, "", 151, "vo_empress_104301_003", "幻境竜后とやら…マジで\n洒落になんねえな。だからって\n引き下がるわけにゃいかねえ！\n持ちこたえてやるぜ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "マコト", 104302, "", 1, "vo_empress_104301_004", 5, "", 152, "vo_empress_104301_004", "どんな強い敵でも\n恐れる必要なんてないよな\nさあ、いっしょに─最大パワーで\nブチのめしてやろうぜっ！", 104301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イリヤ", 104401, "", 1, "vo_empress_104401_001", 5, "", 153, "vo_empress_104401_001", "ここはいずれわらわが支配する世界\nつまり、わが領地に等しきもの…\n奴らのような不届き者の蛮行、\n見過ごすわけにはいかぬわ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イリヤ", 104401, "", 1, "vo_empress_104401_002", 5, "", 154, "vo_empress_104401_002", "厳しい戦いになりそうじゃな…\nお主もわらわから離れるでないぞ\nも、もちろん、大人の姿を保つのに\n都合がいいからというだけじゃ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "イリヤ", 104401, "", 1, "vo_empress_104401_003", 5, "", 155, "vo_empress_104401_003", "何とも恐ろしく禍々しい力じゃ…\nだが、我が意志は決して挫けぬ\n高貴なる吸血鬼の誇りに懸けて、\n最後まで戦い抜いてみせようぞ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "イリヤ", 104401, "", 1, "vo_empress_104401_004", 5, "", 156, "vo_empress_104401_004", "己が誰を敵に回したのかを、\n骨の髄まで知らしめてやろうぞ\nここにいるのは固き絆で結ばれし\n伝説の吸血鬼とその眷属じゃ！", 104401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クウカ", 104501, "", 1, "vo_empress_104501_001", 5, "", 157, "vo_empress_104501_001", "とっても強そうな敵ですっ…\n当然、攻撃も強烈になるはず…\nドＳさん、ここはどうかクウカに、\n先頭をお任せください！　ぐふふ♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クウカ", 104501, "", 1, "vo_empress_104501_002", 5, "", 158, "vo_empress_104501_002", "安心してドＳさんに虐げてもらう\nためにもクウカは負けられませんっ\nこの世界で一番のドＭとして、\n全力で責められに行ってきますっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クウカ", 104503, "", 1, "vo_empress_104501_003", 5, "", 159, "vo_empress_104501_003", "ううっ、刺激が強すぎますよ…っ\nだけど、ドＭのプライドにかけて\nここで退くわけにはいきませんっ！\nドＳさんのこと、守り抜きます…っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クウカ", 104502, "", 1, "vo_empress_104501_004", 5, "", 160, "vo_empress_104501_004", "その視線は、『全部終わったらたっ\nぷり調教してやるからな』という\n意味ですね！　ぐふふっ…♪　負け\nられない理由がまた一つできました", 104501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "タマキ", 104601, "", 1, "vo_empress_104601_001", 5, "", 161, "vo_empress_104601_001", "強そうなやつらが目白押しにゃ～\n短期戦でどうにかならないなら…\n長丁場に向けて、特別価格の\nたい焼きはいかがかにゃ～？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "タマキ", 104601, "", 1, "vo_empress_104601_002", 5, "", 162, "vo_empress_104601_002", "ファントムキャッツは\n狙った獲物を逃がさないにゃ！\nあたしたちの未来を手に入れるまで\nとことんやってやるにゃ～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "タマキ", 104603, "", 1, "vo_empress_104601_003", 5, "", 163, "vo_empress_104601_003", "にゃにゃっ、これが幻境竜后…\nとんでもない力だにゃ\nでも、ここで逃げたらファントム\nキャッツの名が廃るにゃ～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "タマキ", 104602, "", 1, "vo_empress_104601_004", 5, "", 164, "vo_empress_104601_004", "ファントムキャッツにかかれば\nどんなに強い悪党でも\n滅びる運命にゃ！\nとっておきの一撃、キメるにゃ～！", 104601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ジュン", 104701, "", 1, "vo_empress_104701_001", 5, "", 165, "vo_empress_104701_001", "全軍展開！　敵の一体たりとも\nこの先へは進ませるな\n苦しいときは、私の背中を見るんだ\n我々は決して折れはしない！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ジュン", 104701, "", 1, "vo_empress_104701_002", 5, "", 166, "vo_empress_104701_002", "少年…\n最前線は危険だが、下がるつもりは\nないのか？　ふふ、やはり強情だな\nならば、私の隣を絶対に離れるな", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ジュン", 104701, "", 1, "vo_empress_104701_003", 5, "", 167, "vo_empress_104701_003", "な…なんだ…この冷たい闘気は…！\nみんな、いったん退がれ！\n安心しろ、ここは私が防ぎきる\n…たとえ…この身に代えても", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ジュン", 104701, "", 1, "vo_empress_104701_004", 5, "", 168, "vo_empress_104701_004", "幻境竜后、貴様は絶対に勝てないよ\n自分の身以上に、大切な誰かを\n守りたいという、人間の持つ尊い\n想いを、知ることのない貴様は…！", 104701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミフユ", 104801, "", 1, "vo_empress_104801_001", 5, "", 169, "vo_empress_104801_001", "バイト仲間とこの世界のみんなを\n守るために！　私たちのやるべき\nことはただ一つ！　いいわね？\n─最高の効率で倒すわよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミフユ", 104801, "", 1, "vo_empress_104801_002", 5, "", 170, "vo_empress_104801_002", "相手も数が多いし、短期決戦とは\nいかないわね…って！　早く\n勝たなきゃバイトに遅刻しちゃう\nもっと効率アップしていくわよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミフユ", 104803, "", 1, "vo_empress_104801_003", 5, "", 171, "vo_empress_104801_003", "幻境竜后……本当に圧倒的な力ね\nだからってそう簡単に諦められる\nわけはないわよね。たとえそれが\n非効率的な判断だとしても……！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミフユ", 104802, "", 1, "vo_empress_104801_004", 5, "", 172, "vo_empress_104801_004", "こんなに迂遠で非効率的な計画を\n立てる敵になんて負けないわ！\n効率を極めた私たちの一撃を\n叩きつけてやりましょう！", 104801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シズル", 104902, "", 1, "vo_empress_104901_001", 5, "", 173, "vo_empress_104901_001", "安心していいよ、弟くん♪\n弟くんには指一本触れさせない！\n絶対に弟くんを守るから…だって\nそれがお姉ちゃんの役目だもんね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シズル", 104902, "", 1, "vo_empress_104901_002", 5, "", 174, "vo_empress_104901_002", "準備はできてる、弟くん？\n不安なら手をつないであげよっか？\n大丈夫、お姉ちゃんと弟くんなら\n悪いやつらを全部倒せるはず♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "シズル", 104903, "", 1, "vo_empress_104901_003", 5, "", 175, "vo_empress_104901_003", "幻境竜后…手強そうだね…\nでも諦めないよ、絶対に！\n弟くんとお姉ちゃんの大切な世界\nきっと守り抜いてみせるんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "シズル", 104902, "", 1, "vo_empress_104901_004", 5, "", 176, "vo_empress_104901_004", "お姉ちゃんと弟くんの力を合わせて\n二人の未来を、みんなの未来を\n一緒に守ろっ！　あ、終わったら\nたくさん甘えさせてあげるからね♪", 104901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミサキ", 105001, "", 1, "vo_empress_105001_001", 5, "", 177, "vo_empress_105001_001", "アブナイキレイなお姉さんはね\n『ふれーばー』だから許されるの！\nこんなメチャクチャにするなんて…\n本物の大人のレディが勝負よ勝負！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミサキ", 105001, "", 1, "vo_empress_105001_002", 5, "", 178, "vo_empress_105001_002", "アタシは全世界代表の\n大人のレディなんだから！\nアンタ！\nしっかりエスコートしてよね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミサキ", 105003, "", 1, "vo_empress_105001_003", 5, "", 179, "vo_empress_105001_003", "コ、コイツが幻境竜后…っ\n…正直怖いけど…絶対に逃げないわ\n大人のレディのプライドにかけて\n戦い抜いてやるんだから…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミサキ", 105002, "", 1, "vo_empress_105001_004", 5, "", 180, "vo_empress_105001_004", "終わったらデートよ！　だって…\n約束があった方がやる気出るもん♪\nよーし！　大人のレディとして\n最後はエレガントに決めるわよ！", 105001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミツキ", 105101, "", 1, "vo_empress_105101_001", 5, "", 181, "vo_empress_105101_001", "なんて重圧かしら…でも、あいにく\n私も伊達に修羅場をくぐってないの\nさあ、かかってきなさい！\n裏の人生経験、見せてあげるわ…♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミツキ", 105101, "", 1, "vo_empress_105101_002", 5, "", 182, "vo_empress_105101_002", "私は闇医者である前に科学者なの\nあなたたち、実験に協力してくれる\nわよね？　隻眼の悪魔の名は\n伊達じゃないのよ？　覚悟しなさい", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミツキ", 105101, "", 1, "vo_empress_105101_003", 5, "", 183, "vo_empress_105101_003", "到底不可能に思える挑戦こそ\n科学者の腕の見せどころなのよ\n青い薔薇のごとく、人の信念が\n起こす奇跡を見せてあげるわ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミツキ", 105101, "", 1, "vo_empress_105101_004", 5, "", 184, "vo_empress_105101_004", "迷いのない言葉をもらったんだもの\n私だってもう、覚悟を決めたわ\nこの先の未来を君と生きていく…\nそのために全力をぶつけるだけよ！", 105101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リマ", 105201, "", 1, "vo_empress_105201_001", 5, "", 185, "vo_empress_105201_001", "私のお友達をいじめるなら\n相手になるわ！\nたとえ魔物に間違えられても\n絶対にここを引かないから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "リマ", 105201, 1, 1, "vo_empress_105201_002", 3, 10000, 186, "vo_empress_105201_002", "ね、ねぇ…\nちょっと聞きたいんだけど\n毛皮もないのにあの姿なのよね？\n風邪引いたりしないのかしら？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "リマ", 105201, "", 1, "vo_empress_105201_003", 5, "", 187, "vo_empress_105201_003", "ひづめは割れちゃいそうだし…\n毛並みだってボロボロだし…\nでも後ろには彼がいるんだもの\n恋する乙女の負けられない戦いよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "リマ", 105202, "", 1, "vo_empress_105201_004", 5, "", 188, "vo_empress_105201_004", "私はもう恋する女の子じゃないわ…\n王子様の愛を受け取ったお姫様よ！\n彼が私を守ってくれるように\n私が彼を守ってみせるわ！", 105201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "モニカ", 105303, "", 1, "vo_empress_105301_001", 5, "", 189, "vo_empress_105301_001", "どれほど強大な敵であろうと、\n我々【ヴァイスフリューゲル\nランドソル支部】がいれば安心…\nこら！　皆纏まって行動しろー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "モニカ", 105301, "", 1, "vo_empress_105301_002", 5, "", 190, "vo_empress_105301_002", "敵戦力は強大無比…だが、\n私たちなら必ず倒せるはずだ！\n白き翼の名のもとに、今こそ\n正義の鉄槌を下してやる！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "モニカ", 105301, "", 1, "vo_empress_105301_003", 5, "", 191, "vo_empress_105301_003", "これが幻境竜后の底力か…\n名にし負う圧倒的な強さだな…\nだが！　長期戦になろうとも必ずや\n私たちが勝利の旗を掲げるのだ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "モニカ", 105302, "", 1, "vo_empress_105301_004", 5, "", 192, "vo_empress_105301_004", "貴公と一緒ならば\nなんだってできるとも\nさあ、最後の一撃を加えてやろう！", 105301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ツムギ", 105401, "", 1, "vo_empress_105401_001", 5, "", 193, "vo_empress_105401_001", "強そうな相手ばかりですけど\nだからなんだっていうんですか！\nほら、騎士さんも気合い入れて！\n一緒に戦いますよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "ツムギ", 105403, 1, 1, "vo_empress_105401_002", 3, 10000, 194, "vo_empress_105401_002", "なんか敵に下着姿…っていうか\nほぼ裸みたいな人いません？\n…え？　あれ趣味なんですか？\nあの人の？　…正気ですか？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ツムギ", 105403, "", 1, "vo_empress_105401_003", 5, "", 195, "vo_empress_105401_003", "世界を作り変えようなんて\n幻境竜后、絶対許せません…！\nあとその服！　そんなに破いて！\nデザイナーが泣いてますよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ツムギ", 105401, "", 1, "vo_empress_105401_004", 5, "", 196, "vo_empress_105401_004", "私と騎士さんの糸は\n絶対に切れません！\nだから…今ここで\nすべてを終わらせましょう！", 105401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アユミ", 105503, "", 1, "vo_empress_105501_001", 5, "", 197, "vo_empress_105501_001", "つ、強そうな人たちばっかり…\n逃げたいくらいだけど、\nそれはダメ。先輩をケガさせない\nためにも、私も頑張らなくちゃ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アユミ", 105501, "", 1, "vo_empress_105501_002", 5, "", 198, "vo_empress_105501_002", "私なんかが大それたことを言うのは\n笑われるかも…でも…！\n先輩を守るために、\n世界を守ってみせます…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アユミ", 105503, "", 1, "vo_empress_105501_003", 5, "", 199, "vo_empress_105501_003", "な、なんて大きさ、存在感…！\nまるで私とは真逆の人…\nこうして立ってるだけで、\n私、消えちゃいそうです～っ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アユミ", 105502, "", 1, "vo_empress_105501_004", 5, "", 200, "vo_empress_105501_004", "先輩がそばにいてくれる…\nそれだけで勇気が湧いてきて\n前へ進む力がもらえるんです\n行きましょう、先輩！", 105501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ルカ", 105601, "", 1, "vo_empress_105601_001", 5, "", 201, "vo_empress_105601_001", "雁首並べてよくもまあ…\nこりゃ長丁場になりそうだ\n釣りと同じくじっくり腰を据えて\n勝負しようじゃないか", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ルカ", 105601, "", 1, "vo_empress_105601_002", 5, "", 202, "vo_empress_105601_002", "世界の危機とあっちゃあ\nアタシたち黄昏時の住人でも\n黙っちゃいられないね！\nひとっ働きさせてもらおうかい！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ルカ", 105603, "", 1, "vo_empress_105601_003", 5, "", 203, "vo_empress_105601_003", "へぇ、これが幻境竜后かい…\nたいそうな強さだけど、アタシも\nここで退くわけにはいかないんだ\n心に差した刃に懸けて、いくよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ルカ", 105602, "", 1, "vo_empress_105601_004", 5, "", 204, "vo_empress_105601_004", "刀も恋も揃ったアタシは天下無双！\nお前さんが側にいてくれれば、\nどんな巨悪にだって勝てるよ！", 105601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ペコリーヌ", 105803, "", 1, "vo_empress_105801_001", 5, "", 205, "vo_empress_105801_001", "また一緒に、みんなで\nおいしいごはんを食べるために！\nわたしたちは、絶対に負けません！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, "ペコリーヌ", 105801, 1, 1, "vo_empress_105801_002", 3, 10000, 206, "vo_empress_105801_002", "フレイヤさんだけじゃなく、\n覇瞳皇帝やミロクまで！\n長丁場になりそうです…\n栄養補給はしっかりしましょうね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ペコリーヌ", 105803, "", 1, "vo_empress_105801_003", 5, "", 207, "vo_empress_105801_003", "これが、幻境竜后の力…\nやばいですね。正直、どうやって\n止めればいいのか分かりません\nでもここで引き下がるわけには…っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ペコリーヌ", 105802, "", 1, "vo_empress_105801_004", 5, "", 208, "vo_empress_105801_004", "あなたの愛情でお腹いっぱいの\n無敵ペコリーヌ参上です☆\nわたしたちの明日を、この世界を\n全力全開で取り戻しましょう！", 105801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "コッコロ", 105903, "", 1, "vo_empress_105901_001", 5, "", 209, "vo_empress_105901_001", "みなさまとのおいしいごはんのため\n負けるわけにはまいりません\n主さま、お背中はお任せください\nわたくしがお守りいたします！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "コッコロ", 105905, "", 1, "vo_empress_105901_002", 5, "", 210, "vo_empress_105901_002", "敵は強大…ですが、心強い仲間の\nみなさまが一緒でございます\n…全員主さまとお知り合いなのは\n未だに信じられませんが…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "コッコロ", 105903, "", 1, "vo_empress_105901_003", 5, "", 211, "vo_empress_105901_003", "まだこのような力が…！？\n主さま、ここはお下がりください\nたとえこの身に何があろうと、\nあなただけはお守りいたします…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "コッコロ", 105902, "", 1, "vo_empress_105901_004", 5, "", 212, "vo_empress_105901_004", "主さまとの絆がある限り\nわたくしは絶対に負けません！\nいついかなるときも、何があろうと\nわたくしが導いてみせます！", 105901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "キャル", 106001, 1, 1, "vo_empress_106001_001", 3, 10000, 213, "vo_empress_106001_001", "また陛下と戦うのね…大丈夫、一番\n大事なものが何なのかは分かってる\n…だから、あたしも負けないわ\n─陛下、よろしくお願いします！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "キャル", 106003, "", 1, "vo_empress_106001_002", 5, "", 214, "vo_empress_106001_002", "この世界を好き勝手しようだなんて\nそういう連中に人生振り回されるの\nこちとらもううんざりなのよ！\n全員ぶっ飛ばしてやるんだから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "キャル", 106003, "", 1, "vo_empress_106001_003", 5, "", 215, "vo_empress_106001_003", "なんなのよあの力、反則でしょ…\nだけどさ、どんなに怖くたって\nあたしはここから退かないわ\n他に行くとこも、ないんだからっ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "キャル", 106002, "", 1, "vo_empress_106001_004", 5, "", 216, "vo_empress_106001_004", "絆の力でパワーアップ、なんて\nガラじゃないと思ってたけど…\n今だけは調子に乗らせてもらうわ\nもう負ける気がしないってねっ！", 106001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ノウェム", 106102, "", 1, "vo_empress_106101_001", 5, "", 217, "vo_empress_106101_001", "晶に直してもらって\n天楼覇断剣も新品同然だ！\n気合い入れていくぞオクトー！\nはーっはっはっはー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ノウェム", 106101, "", 1, "vo_empress_106101_002", 5, "", 218, "vo_empress_106101_002", "真那、覚悟しとけよ！\nオマエが積み上げてきた悪事…\nこの大悪党がまとめて\nぶっ壊してやるからな！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ノウェム", 106103, "", 1, "vo_empress_106101_003", 5, "", 219, "vo_empress_106101_003", "今までの借り…ここでまとめて\n返してやるって、決めてたんだ\nオマエだけは絶対に、許さない\n…オマエが、どれだけ強くても…っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ノウェム", 106102, "", 1, "vo_empress_106101_004", 5, "", 220, "vo_empress_106101_004", "大悪党のプリンセス？\nなんだかよくわからないけど──\nとにかく、あの化け物ぶった斬りに\n行くぞ！　ついてこい！", 106101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シェフィ", 106401, "", 1, "vo_empress_106401_001", 5, "", 221, "vo_empress_106401_001", "絶対に負けられない戦いね\nおいしいごはんと、本当の\nハッピーエンドのために\n気を引き締めていきましょう", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4004, "シェフィ", 106403, 1, 1, "vo_empress_106401_002", 3, 10000, 222, "vo_empress_106401_002", "ミロク…まだ生きていたのね…！\nあの男は私が相手するわ\n兄さんの分もまとめて、\n今ここで借りを返さないと！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "シェフィ", 106401, "", 1, "vo_empress_106401_003", 5, "", 223, "vo_empress_106401_003", "こんな力を隠してたなんて…！\n…まだよ。まだ諦めないわ\nどんな方法を使ってでも\nみんなだけは助けてみせる…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "シェフィ", 106402, "", 1, "vo_empress_106401_004", 5, "", 224, "vo_empress_106401_004", "不思議ね…あなたとの思い出で\n全身に力が満ちていくような気持ち\n…私たちが紡いできた絆を\n幻境竜后に見せてやりましょう", 106401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カヤ", 106501, "", 1, "vo_empress_106501_001", 5, "", 225, "vo_empress_106501_001", "おまえら、ケンカ売りたいんだろ？\nこの世界そのものに！\nならこっち向けよ。喧嘩屋のオレが\nまとめて買ってやるぜ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カヤ", 106501, "", 1, "vo_empress_106501_002", 5, "", 226, "vo_empress_106501_002", "オレがドラゴン族なのも、\nこんな力を持ってるのも…きっと\n今日、この時のためだったんだ\nそうだろ？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "カヤ", 106503, "", 1, "vo_empress_106501_003", 5, "", 227, "vo_empress_106501_003", "ウソだろ…オレが竦んじまってる…\nアイツのあの赤い眼から、眼を\nそらすんじゃねぇ…！　ドラゴン族\nのケンカ最強は…オレ様だろッ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "カヤ", 106501, "", 1, "vo_empress_106501_004", 5, "", 228, "vo_empress_106501_004", "自分の力に、ずっとビビッてた\nでも今は何よりこの力を頼もしく\n感じるぜ。テメェをぶっ倒し…\n明日を迎えるための力がなァ！", 106501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イノリ", 106603, "", 1, "vo_empress_106601_001", 5, "", 229, "vo_empress_106601_001", "どきやがれです！　最強ギャングが\nおまえのシマ分捕りにきたですよ！\nこんだけ仲間がいりゃ楽勝ですね♪\n尻尾巻いて逃げ出しやがれです！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イノリ", 106601, "", 1, "vo_empress_106601_002", 5, "", 230, "vo_empress_106601_002", "あっちもゾロゾロつれてきやがり\nましたね…へんっ、このあたしが\nビビビビるとでもおお思うですか\n…お、お兄さん、どどどこです？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "イノリ", 106603, "", 1, "vo_empress_106601_003", 5, "", 231, "vo_empress_106601_003", "…！　あたしと同じドラゴン族？\nボスをプリンセスナイトに従えて\nたとか…へんっ、信じねーです！\nまあボスより性悪そ…ぴゃああっ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "イノリ", 106602, "", 1, "vo_empress_106601_004", 5, "", 232, "vo_empress_106601_004", "ふっふっふ～ん！　熱い力が\nどんどん溢れてくるですよっ！\nさあ、懲らしめてやるですっ！\nおしりペンペンですよ！", 106601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ホマレ", 106701, "", 1, "vo_empress_106701_001", 5, "", 233, "vo_empress_106701_001", "ふふっ、強そうな子がいっぱいだね\nそれじゃあ、誰が一番か決めよっか\nヴィーちゃんのプリンセスナイトで\n歴代最強は誰なのかを、ね♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ホマレ", 106701, "", 1, "vo_empress_106701_002", 5, "", 234, "vo_empress_106701_002", "ヴィーちゃんてば、そんな子たちと\n一緒にいるほうが楽しいんだ～？\nじゃ、私たちも見せつけないとだね\n遠慮なくやっちゃおう☆　あははっ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ホマレ", 106703, "", 1, "vo_empress_106701_003", 5, "", 235, "vo_empress_106701_003", "これが、ヴィーちゃんの本気…\nとってもとってもすごいなぁ\n怖がりだからこそ、そんなに\n強くなれちゃったのかな…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ホマレ", 106702, "", 1, "vo_empress_106701_004", 5, "", 236, "vo_empress_106701_004", "残念だけど、ヴィーちゃん…\nもうゲームオーバーみたいだよ\nあなたとのどんなゲームも私には…\n全部ドキドキして、楽しかったな", 106701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ラビリスタ", 106802, "", 1, "vo_empress_106801_001", 5, "", 237, "vo_empress_106801_001", "毎度、予想を超える困難ばかり\n押し寄せてくるんだからさ～\nま、アタシと少年が居る以上、\n好きにはさせないよ、ってね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "ラビリスタ", 106801, 1, 1, "vo_empress_106801_002", 3, 10000, 238, "vo_empress_106801_002", "よりによって真那まで相手かぁ…\nこりゃ一筋縄じゃいかなそうだ\n誰に対応するかは任せるけど、\n真那を相手取るなら頼ってよ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ラビリスタ", 106801, "", 1, "vo_empress_106801_003", 5, "", 239, "vo_empress_106801_003", "当然、奥の手も用意してくるよね\n次から次へと用意周到だこと…\nとはいえこっちも負けられない\nこの難局の突破口を探すとしよう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ラビリスタ", 106802, "", 1, "vo_empress_106801_004", 5, "", 240, "vo_empress_106801_004", "七冠…しかも幻境竜后が相手なら\n手は抜けそうにもないね\nはは、でもアタシたちならきっと\n乗り越えられーる！　だよね少年♪", 106801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "ネネカ", 107001, 1, 1, "vo_empress_107001_001", 3, 10000, 241, "vo_empress_107001_001", "真那…ふふ、こんなところで相対\nすることになるとは。いつぞやの\n借り、返してあげますよ。用意は\nいいですね？　マサキも、貴方も", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネネカ", 107001, "", 1, "vo_empress_107001_002", 5, "", 242, "vo_empress_107001_002", "数で私たちを圧倒しようなど…\n底の浅い戦略ですね。返り討ちに\nしてあげましょう…この世界を\nまだ失うわけにはいきませんから", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ネネカ", 107001, "", 1, "vo_empress_107001_003", 5, "", 243, "vo_empress_107001_003", "この力…計算外ではありますが\nそれは予想外という意味では\nありません。ええ、楽しみましょう\n不可能を解く、方程式の探求を", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ネネカ", 107002, "", 1, "vo_empress_107001_004", 5, "", 244, "vo_empress_107001_004", "特等席で観察させてもらいましょう\n貴方の『心』という変数が\n『レジェンドオブアストルム』に\nどのような影響を与えるのかを…", 107001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クリスティーナ", 107101, "", 1, "vo_empress_107101_001", 5, "", 245, "vo_empress_107101_001", "クリスティーナさんのご登場だよ☆\nあっははは……☆　またとない宴だ\n心行くまで愉しもうじゃあないか\n血で血を洗うダンス…滾るな♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "クリスティーナ", 107101, 1, 1, "vo_empress_107101_002", 3, 10000, 246, "vo_empress_107101_002", "真那さまがお出ましか…ワタシは\n本当に運がいいと見える♪　本気で\n刃を交える機会が巡ってくるなど\n願ってもない幸運だよ☆", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クリスティーナ", 107103, "", 1, "vo_empress_107101_003", 5, "", 247, "vo_empress_107101_003", "…ここで退くなど興冷めだろう？\nたとえ足が竦んだとしても…退屈に\n食われるよりもよほどいい！\n最後まで愉しみつくしてやるさ…☆", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クリスティーナ", 107102, "", 1, "vo_empress_107101_004", 5, "", 248, "vo_empress_107101_004", "誤算だったなあ、『幻境竜后』\n他の者ならいざ知らず…\nキサマを殺せる唯一の力\n手にしたのはこの『誓約女君』だ！", 107101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クロエ", 110801, "", 1, "vo_empress_110801_001", 5, "", 249, "vo_empress_110801_001", "ざーす。世界を救う系の光バイトで\n来たんすけど…あ、説明とかは\n大丈夫っす。慣れてるんでノリで\n入れます─おのれ世界の敵め！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "クロエ", 110801, 1, 1, "vo_empress_110801_002", 3, 10000, 250, "vo_empress_110801_002", "なっつ、狐のねえさんいるじゃん\nまだ現役で悪モンやってたんだ\nてか中ボスポジに降格してるくね？\n世界の敵界隈、意外とせちがれーな", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クロエ", 110803, "", 1, "vo_empress_110801_003", 5, "", 251, "vo_empress_110801_003", "なんかヤベーの出てきたな…\nこのカンジ、若干最悪っていうか\nぶっちゃけ流れ変わったくない？\nこっから捲るのは…結構ダルいわ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クロエ", 110802, "", 1, "vo_empress_110801_004", 5, "", 252, "vo_empress_110801_004", "ちょ、聞いて敵、ウケんだけど\nなんかうち主人公だったみたいだわ\n山場でヒロインに力託され系のやつ\nてわけで、勝ち確いただきでーす", 110801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "チエル", 110901, "", 1, "vo_empress_110901_001", 5, "", 253, "vo_empress_110901_001", "ちぇるーん☆　ボス敵のみんな～！\n初めまして＆お久しブリリアント！\n世界の美少女ちえるんでっす！\n今からぼっこぼこにしてあげるね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "チエル", 110901, "", 1, "vo_empress_110901_002", 5, "", 254, "vo_empress_110901_002", "クリスＰの敵はカルミナの敵！\nカルミナの敵はなかよし部の敵！\nツアー全通めざして戦います！\n現場の平和はチエルが守る！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "チエル", 110903, "", 1, "vo_empress_110901_003", 5, "", 255, "vo_empress_110901_003", "あ、あのう…ヤバくないです？\n敵のねえさん、急に年末歌合戦の\nラスボス衣装みたくなりましたけど\nえ、どーしよ…揚げます白旗？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "チエル", 110902, "", 1, "vo_empress_110901_004", 5, "", 256, "vo_empress_110901_004", "世界の敵さん、ごめんちゃい！\nなんか愛だか絆だかの超理論的な\nアレでチエル覚醒しちゃいました！\nちぇるっと終わらせてあげますね！", 110901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユニ", 111001, "", 1, "vo_empress_111001_001", 5, "", 257, "vo_empress_111001_001", "世界の危機だって？　何度目だね？\nざまあみろだよ、勝手に滅べば…\nなに、地球の危機？　この箱庭の\n話ではなく？　何ソレ一大事！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユニ", 111001, "", 1, "vo_empress_111001_002", 5, "", 258, "vo_empress_111001_002", "お、おい…敵が多すぎないか…？\n端の方でわちゃわちゃしてるだけの\n数合わせ要員として来たのだが…\nどういう事だ、聞いてた話と違うぞ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ユニ", 111003, "", 1, "vo_empress_111001_003", 5, "", 259, "vo_empress_111001_003", "あばば…なんだ、あの奇怪な姿は…\nあれが理系をこじらせた者の末路か\n宇宙暗黒理系女…どうしてあんなに\nなるまで放っておいたんだ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ユニ", 111002, "", 1, "vo_empress_111001_004", 5, "", 260, "vo_empress_111001_004", "はん、驕ったな理系の女王よ\n世界は君が思うほど四角くない\n高機能計算機の弾いた数字ごときで\nぼくと彼の行間までは測れまいよ！", 111001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クレジッタ", 118001, "", 1, "vo_empress_118001_001", 5, "", 261, "vo_empress_118001_001", "ですからわたくしは商人で、\n戦いなどは不向き…などと\n言ってる場合ではありませんわね！\n参りますわよ、我が陛下のために！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クレジッタ", 118003, "", 1, "vo_empress_118001_002", 5, "", 262, "vo_empress_118001_002", "ああもうはあもう、あっちこっち\n滅茶苦茶にしてくださってからに！\n復興費用の賠償はどなたに\n請求すればよろしいのかしら！？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クレジッタ", 118003, "", 1, "vo_empress_118001_003", 5, "", 263, "vo_empress_118001_003", "でっか！？　でっっっっか！！！\n幻境竜后でしたかしら！？\nなんなんですのあの高層建築な方、\n建築基準法違反ですわよ～っ！？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クレジッタ", 118002, "", 1, "vo_empress_118001_004", 5, "", 264, "vo_empress_118001_004", "ホーッホッホッホ！　幻境竜后さん\n貴方にはいらっしゃるのかしら！\n利害でなくその理想のために\n命を賭ける、真実の忠臣が！", 118001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ランファ", 118101, "", 1, "vo_empress_118101_001", 5, "", 265, "vo_empress_118101_001", "恐ろしくて強そうな音が…たくさん\nでも…きっと、大丈夫。あなたや、\nミソラちゃん…みんなが一緒で…\nあたたかい音も、たくさんだもの…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ランファ", 118101, "", 1, "vo_empress_118101_002", 5, "", 266, "vo_empress_118101_002", "緊張、してる…？　そ、それなら、\nわたしに、任せて…わたし、歌を、\n歌うわね…聴けばきっと、いつも\n通りの力を、出せると思うから…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ランファ", 118103, "", 1, "vo_empress_118101_003", 5, "", 267, "vo_empress_118101_003", "お、音と声が、すごい…\nなんて…なんて恐ろしいのかしら…\n…？　で、でも…この音。\n幻境竜后も、恐怖…している…？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ランファ", 118102, "", 1, "vo_empress_118101_004", 5, "", 268, "vo_empress_118101_004", "わたしの歌が、どれほど役立つかは\nわからない…そ、それでもっ、\nあなたの力になりたいの…だから\nわたし、精一杯、歌うわね…", 118101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "ミソラ", 118201, 1, 1, "vo_empress_118201_001", 3, 10000, 269, "vo_empress_118201_001", "わー、ミロクさんや覇瞳皇帝さんも\nいるじゃないですか★\nそれじゃあわたしのガトリングで\nご挨拶といきましょっか♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ミソラ", 118201, "", 1, "vo_empress_118201_002", 5, "", 270, "vo_empress_118201_002", "騎士さんと力を合わせればどんな\n敵もほにゃららら～★　って感じで\nなんとかなると思うんですよねー\nほら、主人公補正ってやつで♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ミソラ", 118202, "", 1, "vo_empress_118201_003", 5, "", 271, "vo_empress_118201_003", "復讐って、イイコトですかね？\n悪いコトですかね？まぁとりあえず\nぶっ壊してから考えましょうか\nね、幻境竜后さん─", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ミソラ", 118202, "", 1, "vo_empress_118201_004", 5, "", 272, "vo_empress_118201_004", "騎士さんに選んでもらっちゃいまし\nたし、いらない縁とはバイバイした\nいんですよねー♪　ってわけで、\nここで終わりにさせてもらいます★", 118201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カリン", 118501, "", 1, "vo_empress_118501_001", 5, "", 273, "vo_empress_118501_001", "みなさんの力を信じて、\n私も全力でサポートします\n連携と創意工夫があれば、きっと\nこの難局も乗り越えられます！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カリン", 118502, "", 1, "vo_empress_118501_002", 5, "", 274, "vo_empress_118501_002", "過去最大級の強敵が現れました！\nギルド管理協会を代表して…\nあなたに討伐を依頼します！\n報酬はお望みのままに、ですよ♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "カリン", 118503, "", 1, "vo_empress_118501_003", 5, "", 275, "vo_empress_118501_003", "…っ。さすがの強敵ですね…\nだからこそ、焦りは禁物…です\nあらゆる事態を想定して、ギルドの\nみなさんを支援するのが私の仕事…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "カリン", 118502, "", 1, "vo_empress_118501_004", 5, "", 276, "vo_empress_118501_004", "あなたと共に進めば\nどんな壁も越えられます\n私の、大切な人の無事を信じて…\n今こそ全力を尽くします！", 118501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネビア", 118601, "", 1, "vo_empress_118601_001", 5, "", 277, "vo_empress_118601_001", "あんな奴らを野放しにしてたら\nこの世界が滅茶苦茶にされちゃう！\nでもまぁこれはこれでチャンスよ♪\n最っ高の悪戯の標的にしてあげる！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネビア", 118601, "", 1, "vo_empress_118601_002", 5, "", 278, "vo_empress_118601_002", "私はただのガイド妖精、みんなに\n比べれば大した力も持ってない…\nでも悪戯妖精なりの意地があんのよ\nあいつらに一泡吹かせてやるわ♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ネビア", 118603, "", 1, "vo_empress_118601_003", 5, "", 279, "vo_empress_118601_003", "幻境竜后、なんて力の持ち主なの\n正直きっついわ…でもまだやれる\n私はデータよ、壊れたって\nあんたを守る壁くらいにはなれる…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ネビア", 118602, "", 1, "vo_empress_118601_004", 5, "", 280, "vo_empress_118601_004", "覚悟しなさいっ！\n出来損ないの悪戯妖精をなめたら\n痛い目に遭うって教えてあげる\nさぁ、最高のショーの始まりよ！", 118601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヴァンピィ", 122303, "", 1, "vo_empress_122301_001", 5, "", 281, "vo_empress_122301_001", "むー！　いたずらっこの暴れんぼ\nさんたちは、ヴァンピィちゃんが\nきつーくおしおきしちゃうよ！\n真祖のおつとめですから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヴァンピィ", 122302, "", 1, "vo_empress_122301_002", 5, "", 282, "vo_empress_122301_002", "けんぞくはヴァンピィちゃんの\n背中に隠れてなさいっ。え？\n背中を守りたい？　うん、それなら\nよろしい！　一緒だよ、けんぞく！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヴァンピィ", 122303, "", 1, "vo_empress_122301_003", 5, "", 283, "vo_empress_122301_003", "幻境竜后？　ふーんだ！\nベスちゃんのほーが、ずーっと\n強くてカッコいいですし！\nいくよっ、けんぞくぅ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヴァンピィ", 122302, "", 1, "vo_empress_122301_004", 5, "", 284, "vo_empress_122301_004", "ここはみんなの『いばしょ』！\n壊しちゃうなんて、許さないもん\nヴァンピィちゃん、本気で怒ったよ\nやっちゃうよ、けんぞく！", 122301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アメス", 123002, "", 1, "vo_empress_123001_001", 5, "", 285, "vo_empress_123001_001", "ほら、あんたは余計な心配しないの\nあいつらに好き勝手させないように\n全力でぶつかっていくだけよ\nあたしたちの未来のためにね♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アメス", 123001, "", 1, "vo_empress_123001_002", 5, "", 286, "vo_empress_123001_002", "…あの連中も強くてやばいけど…\n一番やばいのは、こんなにたくさん\n女の子の知り合いがいる\nあんたかもしれないわね…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アメス", 123003, "", 1, "vo_empress_123001_003", 5, "", 287, "vo_empress_123001_003", "なんて相手なの…さすがに想定を\n超えてるわよ…こんなの卑怯よね\nだからってここで逃げやしないわよ\nせめて、あんたを守るくらいは…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アメス", 123002, "", 1, "vo_empress_123001_004", 5, "", 288, "vo_empress_123001_004", "敵がどれだけ強くたって関係ないわ\nあんたの行く道はあたしが照らす\n迷ったらあたしを見なさい\nどこまでだって導いてあげる！", 123001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネア", 123301, "", 1, "vo_empress_123301_001", 5, "", 289, "vo_empress_123301_001", "『レギオンウォー』思い出すな～\nあん時は敵側だったけどー\n今回は騎士きゅんたちの隣で\nネアおねえちゃんもがんばるぞ～♡", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネア", 123301, "", 1, "vo_empress_123301_002", 5, "", 290, "vo_empress_123301_002", "だる～、激ヤバなテキばっかじゃん\n騎士きゅんパワー充電しねーと\nおねえちゃんもギリギリかもー\nとりま、ちゅっちゅ♡　してい？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ネア", 123303, "", 1, "vo_empress_123301_003", 5, "", 291, "vo_empress_123301_003", "激ヤバドラゴン、ガチしんどー…\nま、だからって負ける気ねーけど\nこーゆう時こそ、スライムの\n粘り強さの見せ所っしょ～　ね♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ネア", 123302, "", 1, "vo_empress_123301_004", 5, "", 292, "vo_empress_123301_004", "ンフフフフ～♪　今のアタシ、\n騎士きゅんと一心同体ってやつ～？\nめちゃめちゃアガるわ～♪\n愛の力パねぇ～♡", 123301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クローチェ", 126401, "", 1, "vo_empress_126401_001", 5, "", 293, "vo_empress_126401_001", "ビーッ！　ビーッ！\nあっちもこっちもそっちも\n強そうな人たちでいっぱいですっ！\nセンサーが壊れちゃいそう～っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クローチェ", 126401, "", 1, "vo_empress_126401_002", 5, "", 294, "vo_empress_126401_002", "世界が大変なことになってますっ！\nでもわたしたちは今までだって、\n大変な戦いを乗り越えてきましたっ\nきっと…ううん、絶対勝てますっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クローチェ", 126403, "", 1, "vo_empress_126401_003", 5, "", 295, "vo_empress_126401_003", "ビビービビビーッ！　…ひゃあっ！\nセンサーが壊れちゃいました…！\nしかも、照準が震えちゃって…\n…これが…この感情が、恐怖…？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クローチェ", 126402, "", 1, "vo_empress_126401_004", 5, "", 296, "vo_empress_126401_004", "今のわたしたちに、怖いものなんて\nありませんっ！　敵さんがどんなに\n強くても…わたしとナイトさんの\n特別なパワーは、もっと強いです！", 126401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ライラエル", 126501, "", 1, "vo_empress_126501_001", 5, "", 297, "vo_empress_126501_001", "ジオ・テオゴニアの姫として\nこの星に生きる一個として\nこれ以上の蹂躙を許すわけには\nいきません。そうですね？　騎士", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "ライラエル", 126506, 1, 1, "vo_empress_126501_002", 3, 10000, 298, "vo_empress_126501_002", "穢らわしい、色狂いの山羊めが\n我が従僕を傀儡としてくれた借り、\n兆倍──否、京倍にして\n返してくれようぞ。崩雷夜天！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ライラエル", 126503, "", 1, "vo_empress_126501_003", 5, "", 299, "vo_empress_126501_003", "幻境竜后。迷いなく、圧倒的な力で\nわたしたちの調和を滅しようとする\nそんな力を、認めたくはないのに…\nなんて、困難な戦いなのでしょう…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ライラエル", 126502, "", 1, "vo_empress_126501_004", 5, "", 300, "vo_empress_126501_004", "この星には、あなたがいる…\n悪辣な侵略者と戦う理由など、\nただそれだけで十分です\n守りましょう。わたしたちの世界を", 126501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "リンド", 127701, 1, 1, "vo_empress_127701_001", 3, 10000, 301, "vo_empress_127701_001", "あそこにヴルムを傷つけた人が…！\n…騎士さん、絶対勝ちましょうね\nあの人たちのやったこと、私\n絶対ぜったい許しませんから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リンド", 127701, "", 1, "vo_empress_127701_002", 5, "", 302, "vo_empress_127701_002", "騎士さんたちと出会えたこの世界を\n悪いことになんか使わせません\n作り物だなんて信じられませんけど\n失っちゃいけないものはわかります", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "リンド", 127703, "", 1, "vo_empress_127701_003", 5, "", 303, "vo_empress_127701_003", "まだこんな力が残ってるの…！？\n考えなきゃ、私にできること…\n何か…何かないの…！？\nまた私、何もできないの…？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "リンド", 127702, "", 1, "vo_empress_127701_004", 5, "", 304, "vo_empress_127701_004", "あなたが側にいてくれるから、\n私もこうして戦えます\nチョロいって言われてもいいです\n私にとって、大切なひとですから", 127701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヴルム", 127801, "", 1, "vo_empress_127801_001", 5, "", 305, "vo_empress_127801_001", "…正直、サボりとかじゃなくて…\nぜんぜん身体はきついです。でも…\n姉貴やみんなと過ごすこの世界は\n誰にも壊させやしませんから…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "ヴルム", 127801, 1, 1, "vo_empress_127801_002", 3, 10000, 306, "vo_empress_127801_002", "騎士さん…アルシャトのこと\nあたしにも一発殴らせてください\nふざけた真似してくれたお礼…\n倍にして返してやりますよ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヴルム", 127803, "", 1, "vo_empress_127801_003", 5, "", 307, "vo_empress_127801_003", "冗談きついです、こんなの…\n勝てっこないじゃないですか\nあたしだってドラゴン族なのに\nこれほどまでに差があるだなんて…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヴルム", 127802, "", 1, "vo_empress_127801_004", 5, "", 308, "vo_empress_127801_004", "もう後先考えずにいきますよ\n面倒見てくれる人がここにいるので\nあたしと騎士さんが揃えば\n無敵だってとこ見せてやります", 127801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "エリス", 129001, 1, 1, "vo_empress_129001_001", 3, 10000, 309, "vo_empress_129001_001", "覇瞳皇帝…わたしの邪魔をするなら\nかつてのように、消去するだけ\nミロクも…わたしを草野優衣の\n複製と呼んだこと、後悔させてやる", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "エリス", 129001, "", 1, "vo_empress_129001_002", 5, "", 310, "vo_empress_129001_002", "管理者の座は失っても\nわたしの意志は揺らがない…\n騎士クンの物語を紡ぐために…\nそれが、わたしの全てだから", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "エリス", 129003, "", 1, "vo_empress_129001_003", 5, "", 311, "vo_empress_129001_003", "これが七冠、幻境竜后の全力…\n管理者だったかつてのわたしを、\n超えるほどの脅威…でも、\n騎士クンだけは、守ってみせる…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "エリス", 129002, "", 1, "vo_empress_129001_004", 5, "", 312, "vo_empress_129001_004", "孤独も絶望も越えてきた\nもうどんな闇にも迷わない\n騎士クンが隣にいる限り\nわたしは、負けない", 129001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アネモネ", 129601, "", 1, "vo_empress_129601_001", 5, "", 313, "vo_empress_129601_001", "リアを──媛を、傷つけたひとたち\n笑ってられるのも今だけです──\nアルラウネの棘の鋭さ、\n教えてあげますから──", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アネモネ", 129601, "", 1, "vo_empress_129601_002", 5, "", 314, "vo_empress_129601_002", "騎士のひと──背中は、任せます\n貴方のこと、\n媛と同じくらい、信じてるので──\n自分でも、びっくりですけど", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アネモネ", 129603, "", 1, "vo_empress_129601_003", 5, "", 315, "vo_empress_129601_003", "私、ずっと抗ってきたんです\nそのために、強くなったはず──\nだから──諦めたく、ないです…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アネモネ", 129601, "", 1, "vo_empress_129601_004", 5, "", 316, "vo_empress_129601_004", "体が熱くて、思考がまとまらなくて\nなのに負ける気がしない──なんて\nよくわからないです。どうしてか、\n後で教えてください──騎士のひと", 129601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネフィ＝ネラ", 129701, "", 1, "vo_empress_129701_001", 5, "", 317, "vo_empress_129701_001", "難敵強敵揃い踏みなれど\nわっちらが退く理はありんせん\n騎士殿や、手を携えて此度の争乱\n鎮めて見せましょう也", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ネフィ＝ネラ", 129701, "", 1, "vo_empress_129701_002", 5, "", 318, "vo_empress_129701_002", "今のわっちが萎弱であろうとて\n貴様等如き梟悪に斃される訳には\nゆかぬ也。再び足甲を舐めさせ\n地に臥すまで仕置きを致しんしょう", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ネフィ＝ネラ", 129703, "", 1, "vo_empress_129701_003", 5, "", 319, "vo_empress_129701_003", "我が矜持『不退転』─如何なる敵で\nあろうとも揺らぐ仕儀はなし。斯様\nな邪竜程度、退けむと思い侍りしが\n─難儀な由、残念至極─…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ネフィ＝ネラ", 129702, "", 1, "vo_empress_129701_004", 5, "", 320, "vo_empress_129701_004", "参りまする也、騎士殿や\n懼るること等何一つ御座りんせん\n唯わっちらの勇儀を以て、此の星の\n明日を再び…掌中に致しんしょう", 129701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, "ヤマト", 130001, 1, 1, "vo_empress_130001_001", 3, 10000, 321, "vo_empress_130001_001", "─おや、フレイヤじゃないか\nずいぶん様変わりしたようだが\n今の方がアタシとしちゃ好みだね\nお礼参りのしがいもあるってもんさ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヤマト", 130001, "", 1, "vo_empress_130001_002", 5, "", 322, "vo_empress_130001_002", "…フゥン？　あっちもこっちも\n『王家の装備』を持ってるらしいね\n宝の山ってのはこのことかい\nまとめて搔っ攫ってやろうかね…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヤマト", 130003, "", 1, "vo_empress_130001_003", 5, "", 323, "vo_empress_130001_003", "ちっ…、幻境竜后つったかい\n世界を奪おうってのも冗談じゃ\nなさそうだ。…ワカナ、フブキ…\nお前たちだけでも、逃げな…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヤマト", 130002, "", 1, "vo_empress_130001_004", 5, "", 324, "vo_empress_130001_004", "アタシらの住み家を奪おうだぁ？\nハッ、笑わせてくれるね\n盗賊は盗むモンであって、\n盗まれるモンじゃあないンだよ！", 130001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ワカナ", 130101, "", 1, "vo_empress_130101_001", 5, "", 325, "vo_empress_130101_001", "つ、強そうな人たちがたくさん…\nなのに姉さんもフブキちゃんも\nやる気満々だし…\nわたし、どうすればいいのぉ～っ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ワカナ", 130101, "", 1, "vo_empress_130101_002", 5, "", 326, "vo_empress_130101_002", "きっと、長期戦になりますよね…\nあ、あの…ご飯、食べませんか？\nお腹が空くといけないと思って、\n作ってきたので…よろしければっ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ワカナ", 130103, "", 1, "vo_empress_130101_003", 5, "", 327, "vo_empress_130101_003", "む…むりっ！　無理ですよ～っ！\nあんなおっきいドラゴンなんて、\n勝てるわけないじゃないですかっ\nに、逃げちゃいましょ、ねっ…！？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ワカナ", 130102, "", 1, "vo_empress_130101_004", 5, "", 328, "vo_empress_130101_004", "と、盗られるぐらいなら盗るのが\n【バンディ・シスターズ】流ですっ\n騎士さん、わたしたちの未来を\n掴み取りにいきましょう…っ！", 130101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "フブキ", 130201, "", 1, "vo_empress_130201_001", 5, "", 329, "vo_empress_130201_001", "だる～、ささっと片付けてきてよ～\nムリ？　知ってる～だってザコザコ\nお兄さんだもんね♪　しょーがない\n助けてあげよっかな～？きゃはは♡", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "フブキ", 130201, "", 1, "vo_empress_130201_002", 5, "", 330, "vo_empress_130201_002", "あの陰気ダサダサメガネさー、\n仲間集めてチョーシ乗ってねー？\nザコは何匹集まったってザコだって\nフブキちゃんが教えてあげまーす♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "フブキ", 130203, "", 1, "vo_empress_130201_003", 5, "", 331, "vo_empress_130201_003", "ふぇぇ…まじムリ、アイツムリ～！\n全然ラスボスってカンジじゃん！？\nぼくお家かえるぅ～っ！\nお兄さんも一緒にかえろっ、ねっ？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "フブキ", 130202, "", 1, "vo_empress_130201_004", 5, "", 332, "vo_empress_130201_004", "お兄さん、やる気漲っちゃってる？\nだよねー、世界が滅んじゃったら\nぼくとも永遠のお別れなんだし？\n必死になるのもトーゼンっしょ～♡", 130201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クルル", 130901, "", 1, "vo_empress_130901_001", 5, "", 333, "vo_empress_130901_001", "はわっ！？　すっごくすっごく\n悪そうな人達いっぱいですますぅ！\nかばばん君、警備員モードです！\nぴっぴーーーー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クルル", 130901, "", 1, "vo_empress_130901_002", 5, "", 334, "vo_empress_130901_002", "この戦いが終わったら、みなさんと\nパークで凱旋パレードですぅ♪\n…ふぇっ？\n気が早いですますか？", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クルル", 130903, "", 1, "vo_empress_130901_003", 5, "", 335, "vo_empress_130901_003", "はわわっ！　幻境竜后さん、\n強そうすぎですっ…でもっ！\nやっと再建したパークも世界も\nぜったい壊させないですよ～っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クルル", 130902, "", 1, "vo_empress_130901_004", 5, "", 336, "vo_empress_130901_004", "ヒーローさんのこと、\nクルルの全部でお助けしますです！\nジオ・テオゴニアでも、どんな世界\nでも…ずっと、ず～っとですっ！", 130901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ルイズマリー", 132301, "", 1, "vo_empress_132301_001", 5, "", 337, "vo_empress_132301_001", "なっなんなのよこいつらっ！\nダーリンとの恋路を邪魔する気…？\nそんなことさせないわ…だって、\n二人の恋はエターナルですからっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ルイズマリー", 132301, "", 1, "vo_empress_132301_002", 5, "", 338, "vo_empress_132301_002", "愛情×愛情＝無限大…\n遂に錬金術の神髄に辿り着いたわ…\nさあ…お見舞いしてやりましょう！\n私とダーリンの究極錬成をっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ルイズマリー", 132303, "", 1, "vo_empress_132301_003", 5, "", 339, "vo_empress_132301_003", "あ、あなたがどんなに強くても、\n私は逃げないわ！　ダーリンに\nちょっかいかける奴は絶対に\n許さないって決めてるから…っ！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ルイズマリー", 132302, "", 1, "vo_empress_132301_004", 5, "", 340, "vo_empress_132301_004", "悪いけど速攻で終わらせちゃうわ！\n早く帰ってダーリンと心行くまで\n破廉恥な乳繰り合い…じゃなくて！\n愛を確かめ合うんだからっ！", 132301, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イロハ", 132401, "", 1, "vo_empress_132401_001", 5, "", 341, "vo_empress_132401_001", "わわっ、敵がいっぱい！\nこれがクワガタだったら最高…よし\n新種のクワガタって事にしちゃお！\nあははっ！　待て待て～っ！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "イロハ", 132401, "", 1, "vo_empress_132401_002", 5, "", 342, "vo_empress_132401_002", "あはは、まだまだ出てくるね～！\nなら新しい技いっぱい\n試しちゃおっか…さあ、いくよ！\n──イスルギ流奥義っ！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "イロハ", 132401, "", 1, "vo_empress_132401_003", 5, "", 343, "vo_empress_132401_003", "あのおねーさんもなかなか良いツノ\n持ってるねえ♪　イロハが勝ったら\nルイちゃんと二人でクワガタ相撲\nごっこやってもらおっと！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "イロハ", 132402, "", 1, "vo_empress_132401_004", 5, "", 344, "vo_empress_132401_004", "おねーさんがどんなに強くたって\nイロハは絶対に負けない！\nおじちゃんが見ててくれてる時の\nイロハは、サイキョーなんだから！", 132401, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ソノ", 132501, "", 1, "vo_empress_132501_001", 5, "", 345, "vo_empress_132501_001", "いや無理無理、戦いとか苦手過ぎる\n…でも君となら、奇跡起こせるかも\n…うわやば、今の忘れて\n若者みたいなこと言っちゃったよ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ソノ", 132501, "", 1, "vo_empress_132501_002", 5, "", 346, "vo_empress_132501_002", "敵、まだいっぱいいるじゃん…\nはあ…残業したくないけど頑張るか\n全部終わったら君からのマッサージ\n期待しとくから、ね", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ソノ", 132503, "", 1, "vo_empress_132501_003", 5, "", 347, "vo_empress_132501_003", "はあ…はあ…幻境竜后だっけ？\nルイちゃんの錬金術より\n出鱈目な強さだね…！\nでもまだまだ諦めない…いくよ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ソノ", 132502, "", 1, "vo_empress_132501_004", 5, "", 348, "vo_empress_132501_004", "こんなに強い敵が相手でも\n諦めなきゃ勝てるんだって\n教えてくれたのは君だよ\nふふ…ありがとね、若者♪", 132501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "グレイス", 133001, "", 1, "vo_empress_133001_001", 5, "", 349, "vo_empress_133001_001", "うーわ。あっちもこっちも\nボス級だらけじゃないですか\nま、ヴァイオレット姫には\n指一本触れさせませんけどね", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, "グレイス", 133003, 1, 1, "vo_empress_133001_002", 3, 10000, 350, "vo_empress_133001_002", "リーザ…今度こそ、決着の時ね\nいくら頭数を揃えても私は…いえ\n私と騎士氏は絶対に負けないわ\nこの槍で、冥界に送り返してあげる", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "グレイス", 133003, "", 1, "vo_empress_133001_003", 5, "", 351, "vo_empress_133001_003", "ぐっ…圧倒的ですね『幻境竜后』\nですが…決してあきらめません\n私には、生きていてほしい人が\nたくさんいますので…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "グレイス", 133002, "", 1, "vo_empress_133001_004", 5, "", 352, "vo_empress_133001_004", "とてつもない強敵を前にしてるのに\nまるで恐怖心を感じません…\n…恋とは、心霊現象よりも\n不思議なものらしいですよ", 133001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ヴァイオレット", 133101, "", 1, "vo_empress_133101_001", 5, "", 353, "vo_empress_133101_001", "恐るべき方々ばかりです…\nですがわたくしは絶対に退きません\nジオ・ニヴルヘルの姫として\nこの世界を守ると決めたのです！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, "ヴァイオレット", 133101, 1, 1, "vo_empress_133101_002", 3, 10000, 354, "vo_empress_133101_002", "リーザ…どうしてもわたくしたちの\n前に立ちはだかるというのですね\nならばわたくしも覚悟を決めました\nこの手であなたを、倒します…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ヴァイオレット", 133103, "", 1, "vo_empress_133101_003", 5, "", 355, "vo_empress_133101_003", "これが、彼女の本気の力…！\n異質で…故に、とても寂しい…\n本当の意味で彼女に届く声が、\nこの世界に存在するのでしょうか…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ヴァイオレット", 133102, "", 1, "vo_empress_133101_004", 5, "", 356, "vo_empress_133101_004", "あなたとの「繋がり」がある限り\n死が牙を剥くことはありません\n手を取り合い、共に参りましょう\nわたくしたちの未来のために！", 133101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "メドゥーサ", 133601, "", 1, "vo_empress_133601_001", 5, "", 357, "vo_empress_133601_001", "フンっ、次から次へと…！　なら\n思う存分、大暴れしてやるから♪\nやっちゃうわよ、メドゥシアナ！\nアンタも！！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "メドゥーサ", 133601, "", 1, "vo_empress_133601_002", 5, "", 358, "vo_empress_133601_002", "どこの誰だか知らないけれど、\nアタシの魔眼でまとめて石に…って\nきゃああああ！　こんなバケモン級\nなら先に教えときなさいよ～っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "メドゥーサ", 133603, "", 1, "vo_empress_133601_003", 5, "", 359, "vo_empress_133601_003", "な…なんなの、アイツの『眼』…\nでもねっ、アタシはメドゥーサ\nゴルゴーンの、お姉ちゃんの妹よ！\n睨みあいで負けるわけがないわ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "メドゥーサ", 133602, "", 1, "vo_empress_133601_004", 5, "", 360, "vo_empress_133601_004", "知ってる？　蛇って執念深いのよ\nこの『眼』で見つけてやったわ\n幻境竜后、アンタが一番恐れること\nアタシとこいつが手をつなぐこと！", 133601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ホウオウ", 134701, "", 1, "vo_empress_134701_001", 5, "", 361, "vo_empress_134701_001", "この大地と大空を守るため、\n人の子らだけに任せてはおけません\n鳳凰のはばたきで、その野望ごと\n跡形もなく吹き飛ばしましょう！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ホウオウ", 134701, "", 1, "vo_empress_134701_002", 5, "", 362, "vo_empress_134701_002", "さあ皆さん、ここが正念場です！\n私がいれば楽勝圧勝間違いなし！\n…えっ？　私が先頭？　えーと…\nあっちょっと待って押さないで！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ホウオウ", 134703, "", 1, "vo_empress_134701_003", 5, "", 363, "vo_empress_134701_003", "羽が散って、ちっ、力が…\n幻境竜后、やるではないですか…\nしかし、私も不死鳥と呼ばれた身…\nただでやられは…ぴ、ぴよぉぉ～…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ホウオウ", 134702, "", 1, "vo_empress_134701_004", 5, "", 364, "vo_empress_134701_004", "幻境竜后、でしたか？\nあなたも運のない方ですね\n今の私は輪廻史上最強の鳳凰\nその鱗一つ残さず焼き尽くします！", 134701, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カノン", 134901, "", 1, "vo_empress_134901_001", 5, "", 365, "vo_empress_134901_001", "ヲ～ッホッホ！　どいつもこいつも\n大層なおツラ構えしてますけどぉ？\nあたくし様の敵じゃありませんわ！\nほら馬ボーン！　お強化なさいな！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "カノン", 134901, "", 1, "vo_empress_134901_002", 5, "", 366, "vo_empress_134901_002", "いってぇ～ですわ！　あたくし様の\nお美しいお肌を傷つけましたわね！\nまとめてお成敗して差し上げますわ\nついてらっしゃいな！　馬ボーン！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "カノン", 134903, "", 1, "vo_empress_134901_003", 5, "", 367, "vo_empress_134901_003", "なんてタマですの…アースハイドラ\nよりデカいなんて聞いてませんわ！\nでも…ここでお尻尾巻いて逃げる\nなら、死んだ方がマシですわ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "カノン", 134902, "", 1, "vo_empress_134901_004", 5, "", 368, "vo_empress_134901_004", "幻境竜后とやら、お覚悟なさいな\nあたくしと馬ボーンの前に立つなど\n100億万年お早いですわ！\n華麗にお成敗して差し上げますわ♪", 134901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アイラ", 135501, "", 1, "vo_empress_135501_001", 5, "", 369, "vo_empress_135501_001", "来たね、お姉さんの出番ってやつ♪\nキミと一緒に戦えるなんて、あたし\nテンション最高潮だよ！　あははっ\nさ、思いっきり暴れちゃおっか！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4005, "アイラ", 135501, 1, 1, "vo_empress_135501_002", 3, 10000, 370, "vo_empress_135501_002", "あれが…覇瞳皇帝のオリジナルだね\nま、関係ないや。本物でも偽物でも\n今度こそ決着つけてあげるから！\nお姉さんの拳…燃え盛ってるよー！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アイラ", 135503, "", 1, "vo_empress_135501_003", 5, "", 371, "vo_empress_135501_003", "幻境竜后…とんでもない相手だね\nあたしの拳だって届かないかも…\nそれでも、燃え尽きるまで戦うよ\nキミが信じてくれてる限り、ね！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アイラ", 135502, "", 1, "vo_empress_135501_004", 5, "", 372, "vo_empress_135501_004", "キミがいれば怖いものなし！\nお姉さん今、燃えに燃えてるよっ\n太陽より熱く燃える拳で…\n全部まとめてぶっ飛ばす！", 135501, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シナツ", 135601, "", 1, "vo_empress_135601_001", 5, "", 373, "vo_empress_135601_001", "どれほどの逆風の中にいても、\n諦めてはならない…そうだろう？\nかつて私が、他でもないキミたちに\nそう教えてもらったんだ…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "シナツ", 135601, "", 1, "vo_empress_135601_002", 5, "", 374, "vo_empress_135601_002", "私はこの世界の人々と出会い、\n失ったはずの希望を見つけられた\n今度は私が、皆に希望を届ける番だ\nこの刃、存分に振るわせてくれ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "シナツ", 135603, "", 1, "vo_empress_135601_003", 5, "", 375, "vo_empress_135601_003", "幻境竜后…私たちの世界を創造し、\nそして滅ぼそうとした張本人か…！\nその力がどんなに強大だとしても…\n私は…絶対に逃げたりなどしない！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "シナツ", 135602, "", 1, "vo_empress_135601_004", 5, "", 376, "vo_empress_135601_004", "私の刃に、もはや一片の曇りもない\n皆と生きる未来を守り抜くために\n戦いつづける…ただそれだけだ\n─道を阻む者は全て斬り伏せる！", 135601, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, "ユキノ", 135801, 1, 1, "vo_empress_135801_001", 3, 10000, 377, "vo_empress_135801_001", "リ、リ、リーザちゃ…！\nリーザちゃはあてのこと、ヘタレの\nホジナシって思ってっかもだけど…\n前より成長したとこ、見せっから！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ユキノ", 135801, "", 1, "vo_empress_135801_002", 5, "", 378, "vo_empress_135801_002", "田舎者で世間知らずなあてだけど…\n騎士さと一緒にいろんなとこ行って\n大切な思い出、いっぱいできたよ…\nだから守りてぇんだ、この世界…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ユキノ", 135803, "", 1, "vo_empress_135801_003", 5, "", 379, "vo_empress_135801_003", "あ、あても、ちったぁでけぇけど…\n幻境竜后、で、でっかすぎ…！\nそ、それに竜まで…！　炎浴びたら\nあて、溶けちまうよぅ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ユキノ", 135802, "", 1, "vo_empress_135801_004", 5, "", 380, "vo_empress_135801_004", "「あてなんか」なんて、考えね…\n騎士さが信じてくれるなら、\nあてだって自分のこと、信じるよ\nあてと騎士さなら大丈夫、って…！", 135801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, "サツキ", 135903, 1, 1, "vo_empress_135901_001", 3, 10000, 381, "vo_empress_135901_001", "リザ公…手前ェどの面下げて\n俺の前に出てきやがった\nまァいいさ、何聞いても今更だ\nここで落とし前つけてもらうぜ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "サツキ", 135901, "", 1, "vo_empress_135901_002", 5, "", 382, "vo_empress_135901_002", "いつ死んでもいいなんて\nもう思っちゃいねぇさ\nこの悪玉どもより、図太くしぶとく\n生き抜いてやろうじゃねぇか", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "サツキ", 135901, "", 1, "vo_empress_135901_003", 5, "", 383, "vo_empress_135901_003", "あれが幻境竜后か…\nハンパじゃねェや\nしゃあねぇ、こうなりゃ一丁\n死に花咲かすとするか", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "サツキ", 135902, "", 1, "vo_empress_135901_004", 5, "", 384, "vo_empress_135901_004", "世界だの未来だの現実だの…\n重いったらありゃしねぇぜ\n潰れるなよ、騎士公\n俺も一緒に担いでやっからさ", 135901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "アラクネ", 136001, "", 1, "vo_empress_136001_001", 5, "", 385, "vo_empress_136001_001", "騎士さま、どうかご安心を…\nどれだけ厳しい運命が待って\nいたとしても…あなたのことは、\nわたしの糸が必ずお守りします", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4003, "アラクネ", 136001, 1, 1, "vo_empress_136001_002", 3, 10000, 386, "vo_empress_136001_002", "…？　あの金髪の女性、なんだか\n見覚えあるような気が…いえ\n騎士さまの敵は、わたしの敵です\nそれだけです…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "アラクネ", 136003, "", 1, "vo_empress_136001_003", 5, "", 387, "vo_empress_136001_003", "あれが幻境竜后さま…\nなんという恐るべき力\n…騎士さま、わたしの後ろに\n一度くらいは、庇えるはずです…", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "アラクネ", 136002, "", 1, "vo_empress_136001_004", 5, "", 388, "vo_empress_136001_004", "騎士さまという光が、わたしに力を\n与えてくれるのです。ともに未来を\n歩むためにも…この戦いに\n必ず勝ちましょう、騎士さま", 136001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ナーナ", 136201, "", 1, "vo_empress_136201_001", 5, "", 389, "vo_empress_136201_001", "強そうな敵さんがいっぱい～っ！？\nこーなったら、ウルトラとっておき\nドーナツ！　ちょっと湿気てるけど\n…はい騎士ちゃん、あーんっ♪", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ナーナ", 136201, "", 1, "vo_empress_136201_002", 5, "", 390, "vo_empress_136201_002", "ナーナだって頑張れるんだよっ！\n騎士ちゃんに、そう教わったもん！\nだから、すごく怖いけど…でもっ…\nナーナ、逃げたりしないよぉっ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ナーナ", 136201, "", 1, "vo_empress_136201_003", 5, "", 391, "vo_empress_136201_003", "うぅ…あ、足が震えてきちゃった…\nでも動かなきゃ、戦わなきゃっ…\nわかってるのに、でもでもぉ…\nうえぇぇん、やっぱり怖いぃぃ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ナーナ", 136202, "", 1, "vo_empress_136201_004", 5, "", 392, "vo_empress_136201_004", "今のナーナはよわよわウサギじゃ\nないんだよ。騎士ちゃんのためなら\nどんな敵さんだってやっつけちゃう\nつよつよウサギなんだから！", 136201, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4001, "ルルィ", 136903, 1, 1, "vo_empress_136901_001", 3, 10000, 393, "vo_empress_136901_001", "リーザ姉しゃまが裏切ったなんて\nあたち、信じたくないでしゅ…！\nだから直接聞きにいきましゅ\n吸盤ぜんぶで捕まえてでも…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "ルルィ", 136901, "", 1, "vo_empress_136901_002", 5, "", 394, "vo_empress_136901_002", "姫姉しゃまも騎士しゃんも\nみなしゃん戦ってるんでしゅ\nあたちだって負けましぇん！\n一生懸命がんばりましゅ～！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "ルルィ", 136903, "", 1, "vo_empress_136901_003", 5, "", 395, "vo_empress_136901_003", "あ、あの方、こわいでしゅ…！\n丸呑みにされちゃいそうでしゅっ\nうじゅ…がんばりたいでしゅが…\n震えが止まらないでしゅ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ルルィ", 136902, "", 1, "vo_empress_136901_004", 5, "", 396, "vo_empress_136901_004", "あたちは強くないでしゅけど\n騎士しゃんとの約束がありましゅ\nだから誰にも負けましぇん！\nいっちょに、守りましゅよ！", 136901, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "リリ", 139501, "", 1, "vo_empress_139501_001", 5, "", 397, "vo_empress_139501_001", "これから挑む敵がどれだけ強いと\nしても、勇往邁進していきます\nですからこの戦いでも、兄様の\nおそばで戦わせてくださいませ", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "リリ", 139503, 1, 1, "vo_empress_139501_002", 3, 10000, 398, "vo_empress_139501_002", "幻境竜后の手先、アルシャト…！\nリアさんやヴルム様を陥れた貴方を\n決して許す訳には参りません！\n不倶戴天─ここで成敗致します！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "リリ", 139503, "", 1, "vo_empress_139501_003", 5, "", 399, "vo_empress_139501_003", "幻境竜后の力…これほどまでに\n強力無比だとは…で、ですが…\n何があろうとわたくしは兄様を\nお守りします…命に代えても、必ず", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "リリ", 139502, "", 1, "vo_empress_139501_004", 5, "", 400, "vo_empress_139501_004", "兄様への想いと、重ねてきた大切な\n時間が、たくさんの勇気と限界を\n超える奇跡をくれました。全ての人\nを救うため、参りましょう兄様…！", 125801, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "クリア", 139603, "", 1, "vo_empress_139601_001", 5, "", 401, "vo_empress_139601_001", "お兄さん、もし怪我しちゃっても\nすぐに治癒しますからご安心を！\nわたし決めましたから…もう二度と\n自分自身から逃げないって…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (4002, "クリア", 139603, 1, 1, "vo_empress_139601_002", 3, 10000, 402, "vo_empress_139601_002", "…アルシャトさん…\n謝ったって許してあげませんよ？\nあなたの前では、わたしちょっと\nいい子じゃいられませんから…っ！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "クリア", 139603, "", 1, "vo_empress_139601_003", 5, "", 403, "vo_empress_139601_003", "うぅっ…これが本気の幻境竜后…！\n…こんなの勝てっこありませんよ…\n…せめてお兄さんだけでも…なんて\n最後まで…諦めませんからっ…！", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "クリア", 139601, "", 1, "vo_empress_139601_004", 5, "", 404, "vo_empress_139601_004", "お兄さんの気持ちが胸に溢れて…\nあ、えへへ…なんだか視界が\n滲んできちゃいました…♪\nわたしはもう、負けませんよ…っ！", 126001, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "プレシア", 139701, "", 1, "vo_empress_139701_001", 5, "", 405, "vo_empress_139701_001", "てき、いっぱい、しかも、つよすぎ\nけど、まけないよ\nお兄のほっぺ、たべて\nふるぱわー", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (1, "プレシア", 139701, "", 1, "vo_empress_139701_002", 5, "", 406, "vo_empress_139701_002", "ん\nまだまだ、いける\nお兄、パパ、なかま、いる\nむしゃぶるい", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (2, "プレシア", 139703, "", 1, "vo_empress_139701_003", 5, "", 407, "vo_empress_139701_003", "しょうり、みえない\nせいぎ、まもれない\nそんなの、いや\nあきらめないよ、さいごまで", 0, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "プレシア", 139702, "", 1, "vo_empress_139701_004", 5, "", 408, "vo_empress_139701_004", "て、つなぐ\nせいめいりょく、たかまる\nぜったいしょうり！", 126101, 4);
INSERT INTO `v1_023b531b5b8d54770584b28903b465b8bd22527d71bebca30b4eca0a29291aff` VALUES (3, "ティア", 140301, "", 1, "vo_empress_140301_004", 5, "", 409, "vo_empress_140301_004", "七冠、幻境竜后──LoAの開発者\nあんたにコワいコト教えてあげるわ\n些細なバグと思って放置したら\nゲームを壊すこともあるってね…♪", 140301, 4);
